    "slug" TEXT NOT NULL,
    "title" TEXT NOT NULL,
    "intro" TEXT,
    "position" INTEGER NOT NULL,

    CONSTRAINT "flow_project_pkey" PRIMARY KEY ("slug")
);

-- CreateTable
CREATE TABLE "flow_category" (
    "project_slug" TEXT NOT NULL,
    "slug" TEXT NOT NULL,
    "title" TEXT NOT NULL,
    "position" INTEGER NOT NULL,

    CONSTRAINT "flow_category_pkey" PRIMARY KEY ("project_slug","slug")
);

-- CreateTable
CREATE TABLE "flow_document" (
    "project_slug" TEXT NOT NULL,
    "slug" TEXT NOT NULL,
