    "updated_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,

    CONSTRAINT "flow_document_pkey" PRIMARY KEY ("project_slug","slug")
);

-- CreateIndex
CREATE INDEX "flow_document_project_slug_category_slug_position_idx" ON "flow_document"("project_slug", "category_slug", "position");

-- AddForeignKey
ALTER TABLE "flow_category" ADD CONSTRAINT "flow_category_project_slug_fkey" FOREIGN KEY ("project_slug") REFERENCES "flow_project"("slug") ON DELETE RESTRICT ON UPDATE CASCADE;

-- AddForeignKey
ALTER TABLE "flow_document" ADD CONSTRAINT "flow_document_project_slug_category_slug_fkey" FOREIGN KEY ("project_slug", "category_slug") REFERENCES "flow_category"("project_slug", "slug") ON DELETE RESTRICT ON UPDATE CASCADE;


-- Frozen initial catalog. Applied once by Prisma; later deployments never overwrite DB edits.
INSERT INTO flow_project (slug,title,intro,position) VALUES ('common','공통','고객사와 무관하게 반복 적용하는 **프로젝트 수행 표준**입니다. 착수부터 안정화까지의 딜리버리 라이프사이클과 요구사항 변경 통제 흐름을 담습니다.',0);
INSERT INTO flow_category (project_slug,slug,title,position) VALUES ('common','delivery','프로젝트 수행',0);
INSERT INTO flow_document (project_slug,category_slug,slug,position,document) VALUES ('common','delivery','delivery-lifecycle',0,'{"slug":"delivery-lifecycle","title":"프로젝트 수행 표준 흐름","description":"착수 → 요구사항 → 설계 → 개발 → 검수 → 이행 → 안정화","caption":"프로젝트 수행 표준 흐름","direction":"LR","howToRead":["착수 → 요구사항 → 설계 → 개발·검수 → 이행·안정화 순서로 왼쪽에서 오른쪽으로 읽습니다.","시나리오 검수에서 세 갈래로 갈라집니다 — 실패 건은 결함 처리로, 범위 밖 요건은 범위 변경 관리로, 통과하면 데이터 이행으로 넘어갑니다.","초록 점선(주간 스냅샷)은 WBS·개발 진행을 주간 진척 보고로 모으는 시점 흐름입니다.","회색 점선 카드(프로젝트 멤버·표준 정책·레포지토리)는 단계가 아니라 참조하는 기준정보입니다."],"nodes":[{"id":"deal","data":{"kind":"intake","label":"계약 · 수주","sub":"견적 확정 → 계약 체결"}},{"id":"kickoff","data":{"kind":"core","label":"킥오프","sub":"범위·일정·담당자 합의","doc":"착수보고서"}},{"id":"wbs","data":{"kind":"core","label":"WBS 수립","sub":"작업 분해 · 일정 · 마일스톤","doc":"WBS"}},{"id":"interview","data":{"kind":"intake","label":"고객 인터뷰","sub":"현업 업무 청취 · 녹취"}},{"id":"req","data":{"kind":"core","label":"요구사항 정의","sub":"기능 목록 · 우선순위 확정","doc":"요구사항 정의서"}},{"id":"data-request","data":{"kind":"core","label":"자료 요청","sub":"양식·마스터·연동 스펙 수집"}},{"id":"scope-baseline","data":{"kind":"core","label":"개발 범위 확정","sub":"요구사항 ↔ 범위 매핑 베이스라인","doc":"SOW"}},{"id":"arch","data":{"kind":"core","label":"업무 아키텍처 설계","sub":"화면 흐름 · 도메인 경계"}},{"id":"erd","data":{"kind":"core","label":"데이터 모델 (ERD)","sub":"테이블 · 관계 · 시점 데이터","doc":"ERD"}},{"id":"dev","data":{"kind":"core","label":"개발","sub":"스프린트 단위 구현","timing":"주 단위 스프린트"}},{"id":"progress","data":{"kind":"core","label":"진척 보고","sub":"WBS 대비 진행률 · 리스크","timing":"주간","doc":"주간보고"}},{"id":"scenario","data":{"kind":"core","label":"시나리오 검수","sub":"고객이 직접 도는 테스트 케이스","doc":"검수 시나리오"}},{"id":"defect","data":{"kind":"core","label":"결함 처리","sub":"등록 → 배정 → 수정 → 재검증"}},{"id":"change","data":{"kind":"core","label":"범위 변경 관리","sub":"추가 요건 → 영향도 → 합의","doc":"변경 요청서"}},{"id":"migration","data":{"kind":"core","label":"데이터 이행","sub":"기존 시스템 → 신규 적재·검증"}},{"id":"golive","data":{"kind":"core","label":"오픈 (Go-Live)","sub":"운영 전환 · 사용자 교육","doc":"운영 매뉴얼"}},{"id":"stabilize","data":{"kind":"core","label":"안정화","sub":"오픈 직후 집중 대응","timing":"오픈 후 N주"}},{"id":"handover","data":{"kind":"core","label":"인수인계 · 종료","sub":"산출물 이관 · 검수 확인","doc":"완료보고서"}},{"id":"maintenance","data":{"kind":"future","label":"유지보수 전환","sub":"SLA 기반 운영 계약"}},{"id":"m-member","data":{"kind":"master","label":"프로젝트 멤버"}},{"id":"m-manual","data":{"kind":"master","label":"표준 정책·매뉴얼"}},{"id":"m-repo","data":{"kind":"master","label":"레포지토리·환경"}}],"edges":[{"id":"e1","source":"deal","target":"kickoff","kind":"impl"},{"id":"e2","source":"kickoff","target":"wbs","kind":"impl"},{"id":"e3","source":"kickoff","target":"interview","kind":"impl"},{"id":"e4","source":"interview","target":"req","kind":"impl"},{"id":"e5","source":"interview","target":"data-request","kind":"impl"},{"id":"e6","source":"data-request","target":"req","kind":"impl","label":"자료 수신"},{"id":"e7","source":"req","target":"scope-baseline","kind":"impl"},{"id":"e8","source":"wbs","target":"scope-baseline","kind":"impl","label":"일정 반영"},{"id":"e9","source":"scope-baseline","target":"arch","kind":"impl"},{"id":"e10","source":"arch","target":"erd","kind":"impl"},{"id":"e11","source":"erd","target":"dev","kind":"impl"},{"id":"e12","source":"dev","target":"scenario","kind":"impl","label":"기능 완료"},{"id":"e13","source":"wbs","target":"progress","kind":"snapshot","label":"주간 스냅샷"},{"id":"e14","source":"dev","target":"progress","kind":"snapshot"},{"id":"e15","source":"scenario","target":"defect","kind":"impl","label":"실패 건"},{"id":"e16","source":"defect","target":"dev","kind":"impl","label":"수정 요청"},{"id":"e17","source":"scenario","target":"change","kind":"impl","label":"범위 밖 요건"},{"id":"e18","source":"change","target":"scope-baseline","kind":"impl","label":"베이스라인 갱신"},{"id":"e19","source":"scenario","target":"migration","kind":"impl","label":"검수 통과"},{"id":"e20","source":"migration","target":"golive","kind":"impl"},{"id":"e21","source":"golive","target":"stabilize","kind":"impl"},{"id":"e22","source":"stabilize","target":"handover","kind":"impl"},{"id":"e23","source":"handover","target":"maintenance","kind":"future"},{"id":"m1","source":"m-member","target":"kickoff","kind":"master"},{"id":"m2","source":"m-manual","target":"scope-baseline","kind":"master"},{"id":"m3","source":"m-repo","target":"dev","kind":"master"}]}'::jsonb);
INSERT INTO flow_document (project_slug,category_slug,slug,position,document) VALUES ('common','delivery','change-control',1,'{"slug":"change-control","title":"요구사항 변경 · 범위 관리","description":"추가 요건 접수부터 범위 반영 또는 반려까지의 판단 경로","caption":"변경 관리 흐름","direction":"TB","howToRead":["추가 요건은 어디서 왔든 전부 ''변경 요청 등록''을 거쳐 베이스라인(SOW) 대조로 갑니다.","범위 내면 추가 비용 없이 백로그로, 범위 밖이면 영향도 분석 → 공수 산정 → 고객 협의로 갑니다.","고객 협의 결과는 셋 중 하나입니다 — 반려·보류(종료), 금액·기간 변경이면 계약 변경을 거쳐 범위 갱신, 그 외에는 바로 범위·WBS 갱신.","어느 경로든 실제 구현은 개발 백로그 반영을 통해서만 시작됩니다."],"nodes":[{"id":"raise","data":{"kind":"intake","label":"추가 요건 접수","sub":"고객 요청 · 검수 중 발견 · 내부 제안"}},{"id":"register","data":{"kind":"core","label":"변경 요청 등록","sub":"요청자 · 배경 · 기대 효과 기록","doc":"변경 요청서"}},{"id":"baseline-check","data":{"kind":"core","label":"베이스라인 대조","sub":"확정 범위(SOW) 안인지 밖인지 판정"}},{"id":"in-scope","data":{"kind":"core","label":"범위 내 — 결함/보완","sub":"추가 비용 없이 백로그 편입"}},{"id":"impact","data":{"kind":"core","label":"영향도 분석","sub":"공수 · 일정 · 연관 기능 · 리스크"}},{"id":"estimate","data":{"kind":"core","label":"공수 산정 · 견적","sub":"MD 환산 → 금액 · 일정 지연분","doc":"변경 견적서"}},{"id":"review","data":{"kind":"core","label":"고객 협의","sub":"수용 / 보류 / 반려 결정","timing":"주간 정기 회의"}},{"id":"reject","data":{"kind":"master","label":"반려 · 보류","sub":"사유 기록 후 종료"}},{"id":"contract","data":{"kind":"future","label":"계약 변경","sub":"금액·기간 변경 시 계약서 반영","doc":"변경 계약서"}},{"id":"update-scope","data":{"kind":"core","label":"범위 · WBS 갱신","sub":"베이스라인 재설정 · 일정 재배치","doc":"WBS (개정)"}},{"id":"backlog","data":{"kind":"core","label":"개발 백로그 반영","sub":"스프린트 배정 → 구현"}},{"id":"m-policy","data":{"kind":"master","label":"변경 관리 정책"}}],"edges":[{"id":"c1","source":"raise","target":"register","kind":"impl"},{"id":"c2","source":"register","target":"baseline-check","kind":"impl"},{"id":"c3","source":"baseline-check","target":"in-scope","kind":"impl","label":"범위 내"},{"id":"c4","source":"baseline-check","target":"impact","kind":"impl","label":"범위 밖"},{"id":"c5","source":"in-scope","target":"backlog","kind":"impl"},{"id":"c6","source":"impact","target":"estimate","kind":"impl"},{"id":"c7","source":"estimate","target":"review","kind":"impl"},{"id":"c8","source":"review","target":"reject","kind":"master","label":"반려"},{"id":"c9","source":"review","target":"contract","kind":"future","label":"금액·기간 변경 시"},{"id":"c10","source":"contract","target":"update-scope","kind":"future"},{"id":"c11","source":"review","target":"update-scope","kind":"impl"},{"id":"c12","source":"update-scope","target":"backlog","kind":"impl"},{"id":"m1","source":"m-policy","target":"baseline-check","kind":"master"}]}'::jsonb);
INSERT INTO flow_project (slug,title,intro,position) VALUES ('tns','티앤에스','티앤에스의 **가격표 자동 적재**, **HR 통합 업무**, **회계·재무** 흐름과 **데이터베이스 ERD**입니다. 각 카테고리에서 원천 데이터, 사람의 승인·검토 경계, 후속 업무로 이어지는 확정 결과를 확인합니다.',1);
INSERT INTO flow_category (project_slug,slug,title,position) VALUES ('tns','pricelist','가격표 자동 적재',0);
INSERT INTO flow_document (project_slug,category_slug,slug,position,document) VALUES ('tns','pricelist','pricelist-summary',0,'{"slug":"pricelist-summary","title":"가격표 자동 적재 — 요약 흐름","description":"설명용 한 장. 가격표 파일 한 건이 ACTIVE 마스터까지 가는 길","caption":"요약 흐름 — 상세는 «전체 흐름» · «워커 상세» 차트","direction":"TB","nodeWidth":230,"howToRead":["가격표 파일 한 건이 업로드부터 ACTIVE 마스터까지 가는 길만 남긴 설명용 요약입니다. 구현 상세는 «전체 흐름»·«워커 상세» 차트에 있습니다.","분기는 넷뿐입니다 — 아는 구조인가, 검증을 통과했나, 실패를 어디로 되돌리나, 더는 못 고치나.","사람이 개입하는 자리는 둘입니다 — 신규 구조를 추출 전에 확인할 때, 격리된 범위를 활성화 전에 검토할 때.","실패·반려는 버리지 않고 복구 박스에서 원인별로 가장 가까운 단계로 되돌립니다. 원천자료 부족·반려 확정만 보류로 남습니다."],"nodes":[{"id":"upload","data":{"kind":"entry","label":"가격표 업로드 · 배치 생성","sub":["가격 담당자가 PDF · XLSX 올림","같은 파일은 다시 처리하지 않음","원본은 그대로 보관"]}},{"id":"read","data":{"kind":"model","label":"문서 판독","sub":["렌더 · OCR · AI 문서 지도","어느 페이지에 무엇이 있는지"]}},{"id":"route","data":{"kind":"gate","label":"브랜드 구조 판정","sub":["등록된 어댑터와 대조","아는 구조인가 / 바뀌었나 / 처음인가"]}},{"id":"onboard","data":{"kind":"activate","label":"신규 · 변경 구조 온보딩","sub":["구조 카드 → 대표 섹션 파일럿","사람은 구조만 최소 확인","전체 추출은 그 다음"]}},{"id":"extract","data":{"kind":"model","label":"가격 정보 추출","sub":["표 · 제품 블록 단위로 판독","값 + 근거 좌표를 함께 남김"]}},{"id":"assemble","data":{"kind":"deterministic","label":"SKU · 가격 · 관계 조립","sub":["조립은 코드가 결정론적으로","없는 조합을 만들어내지 않음"]}},{"id":"verify","data":{"kind":"verify","label":"검증 · 독립 감사","sub":["기계 검증 V1~V9","다른 모델이 한 번 더 감사"],"doc":"AUDIT-PASS"}},{"id":"gate","data":{"kind":"gate","label":"위험도 게이트","sub":["확실한 범위와 불확실한 범위를 가름"]}},{"id":"auto","data":{"kind":"activate","label":"Tier 1 · 2 — 자동 확정","sub":["검증 전부 통과한 범위","Tier 2 는 반영 후 감시"]}},{"id":"quarantine","data":{"kind":"gate","label":"Tier 3 — 격리 · 사람 검토","sub":["불확실한 범위만 묶어서 격리","나머지는 계속 자동 처리"]}},{"id":"recover","data":{"kind":"gate","label":"복구 — 원인별로 되돌림","sub":["원인을 분류해 가장 가까운 단계로","영향 범위와 그 아래 결과만 무효화","고치면 검증부터 다시 돈다"]}},{"id":"hold","data":{"kind":"failure","label":"실패 · 보류","sub":["기술 실패 · 원천자료 부족 · 반려","운영에는 반영되지 않음"]}},{"id":"master","data":{"kind":"activate","label":"활성화 → ACTIVE 가격 마스터","sub":["감사 통과분만 반영 · 실패하면 되돌림","에디션 전환 · 발효일"]}},{"id":"consume","data":{"kind":"activate","label":"견적 · 발주 · 원가","sub":["격리된 항목은 사용 차단"]}},{"id":"learn","data":{"kind":"activate","label":"학습 환류","sub":["확정 사례 → 어댑터 · 공통 코어","다음 배치의 자동 처리율이 오름"]}}],"edges":[{"id":"a2","source":"upload","target":"read","kind":"impl","tone":"entry"},{"id":"a3","source":"read","target":"route","kind":"impl","tone":"model"},{"id":"a4","source":"route","target":"extract","kind":"impl","tone":"activate","label":"아는 구조"},{"id":"a5","source":"route","target":"onboard","kind":"impl","tone":"gate","label":"신규 · 변경"},{"id":"a6","source":"onboard","target":"extract","kind":"impl","tone":"activate","label":"구조 확정 후"},{"id":"a7","source":"extract","target":"assemble","kind":"impl","tone":"model"},{"id":"a8","source":"assemble","target":"verify","kind":"impl","tone":"deterministic"},{"id":"a9","source":"verify","target":"gate","kind":"impl","tone":"verify"},{"id":"a10","source":"gate","target":"auto","kind":"impl","tone":"activate","label":"Tier 1 · 2"},{"id":"a11","source":"gate","target":"quarantine","kind":"impl","tone":"gate","label":"Tier 3"},{"id":"a12","source":"extract","target":"recover","kind":"impl","tone":"failure","label":"판독 실패"},{"id":"a13","source":"verify","target":"recover","kind":"impl","tone":"failure","label":"검증 실패"},{"id":"a14","source":"quarantine","target":"recover","kind":"impl","tone":"gate","label":"수정 · 반려"},{"id":"a15","source":"recover","target":"route","kind":"ref","tone":"gate","label":"구조가 바뀐 경우"},{"id":"a15b","source":"recover","target":"extract","kind":"ref","tone":"model","label":"판독 오류"},{"id":"a15c","source":"recover","target":"assemble","kind":"ref","tone":"deterministic","label":"값 · 조합 확정"},{"id":"a15d","source":"recover","target":"hold","kind":"impl","tone":"failure","label":"원천자료 부족 · 반려 확정"},{"id":"a16","source":"auto","target":"master","kind":"impl","tone":"activate"},{"id":"a18","source":"master","target":"consume","kind":"impl","tone":"activate"},{"id":"a19","source":"quarantine","target":"learn","kind":"impl","tone":"activate","label":"확정 사례"},{"id":"a20","source":"onboard","target":"learn","kind":"ref","tone":"activate","label":"새 어댑터"},{"id":"a21","source":"learn","target":"route","kind":"ref","tone":"activate","label":"다음 배치는 아는 구조"}]}'::jsonb);
INSERT INTO flow_document (project_slug,category_slug,slug,position,document) VALUES ('tns','pricelist','pricelist-human-review',1,'{"slug":"pricelist-human-review","title":"사람 검토형 파이프라인","description":"PDF 접수부터 운영 활성화까지 기계 처리와 사람 승인 게이트를 번갈아 보는 흐름","caption":"17단계 본선 · 사람 게이트 · revision 재처리 · 운영 승인 경계","direction":"TB","groupDirection":"LR","nodeWidth":280,"howToRead":["번호 순서가 본선입니다. 기계 처리 다음의 주황색 사람 확인 게이트는 정상 검토 대기 상태 REVIEW_PENDING이며, 승인·수정·반려 결과를 기록합니다.","정보나 원천자료가 부족하면 NEEDS_INPUT, 오류나 상위 단계 수정이 발견되면 REWORK_REQUIRED로 분리합니다. 둘은 정상 검토 대기와 다른 상태입니다.","사람이 상위 단계 값을 바꾸면 그 지점 아래 산출물만 STALE로 무효화하고, 덮어쓰지 않은 새 revision으로 가장 가까운 기계 처리 단계부터 재처리합니다.","신규 브랜드와 변경 레이아웃은 전수 검토합니다. 골든 테스트를 반복 통과한 KNOWN 레이아웃만 위험 기반 검토로 낮추되, 최종 활성화는 항상 사람 승인입니다.","워커는 price_import_candidates staging까지만 씁니다. 운영 마스터 활성화는 별도 승인 경계 뒤의 전용 로더만 수행하며, 정책에 따라 2인 승인을 요구할 수 있습니다."],"groups":[{"id":"g-intake","label":"1–4. 접수·텍스트 증거 — 기계 처리와 사람 확인","kind":"entry"},{"id":"g-structure","label":"5–8. 영역·표 골격 — 승인된 구조는 값 추출이 변경할 수 없음","kind":"model"},{"id":"g-values","label":"9–12. 값 추출·후보 조립 — 원본 대조 후 관계 확정","kind":"deterministic"},{"id":"g-validate","label":"13–15. 자동 검증·staging — 워커 쓰기 권한은 여기까지","kind":"verify"},{"id":"g-activate","label":"16–17. 별도 사람 승인 경계 — 운영 마스터 활성화","kind":"activate"},{"id":"g-revision","label":"검토 예외·revision 제어 — 정상 대기와 정보 부족·재처리를 분리","kind":"failure"}],"nodes":[{"id":"pdf-intake","group":"g-intake","data":{"kind":"entry","label":"1. PDF 접수","sub":["원본 PDF 불변 보관","source_hash · 접수 revision 생성"]}},{"id":"scope-review","group":"g-intake","data":{"kind":"gate","label":"2. 사람 확인 — 적재 범위 확정","sub":["REVIEW_PENDING · 브랜드 · 에디션","통화 · 세금 · 전체/부분 PDF","이번 적재 scope 승인"]}},{"id":"text-evidence","group":"g-intake","data":{"kind":"model","label":"3. OCR · 내장 텍스트 · bbox 증거 생성","sub":["페이지 렌더 · OCR · 내장 텍스트 병렬","word/cell bbox · crop · confidence","원본 좌표와 판독값을 함께 보존"]}},{"id":"text-review","group":"g-intake","data":{"kind":"gate","label":"4. 사람 확인 — 텍스트 근거 확정","sub":["REVIEW_PENDING · 원본/overlay 대조","OCR 또는 내장 텍스트 선택","누락 · 오독 수정"]}},{"id":"region-discovery","group":"g-structure","data":{"kind":"model","label":"5. 표 · 제품 영역 발견","sub":["짧고 자기완결 PDF = 직접 추출","긴 문서 · 페이지 간 문맥 = Document Map 가능","표 · 제품 블록 · 규칙 영역 후보"]}},{"id":"region-review","group":"g-structure","data":{"kind":"gate","label":"6. 사람 확인 — 추출 영역 확정","sub":["REVIEW_PENDING · 표 bbox · 제품 블록","규칙 영역 · 연속표 관계","추출 제외 영역 확정"]}},{"id":"skeleton-extract","group":"g-structure","data":{"kind":"deterministic","label":"7. 표 골격 추출","sub":["표 개수 · 행축 · 열축","상품 단위 · 옵션 축","고정 가격 vs 계산형 가격"]}},{"id":"skeleton-review","group":"g-structure","data":{"kind":"gate","label":"8. 사람 확인 — 골격 승인","sub":["REVIEW_PENDING · 골격 승인 또는 수정","승인 skeleton은 revision에 고정","값 추출 단계의 임의 변경 금지"]}},{"id":"value-extract","group":"g-values","data":{"kind":"model","label":"9. 값 추출","sub":["상품 코드 · 옵션 · 가격 · 빈 셀","주문 불가 · 가격 문의","계산식 · 코드 패턴","승인된 골격 안에서만 판독"]}},{"id":"value-review","group":"g-values","data":{"kind":"gate","label":"10. 사람 확인 — 값 대조·수정","sub":["REVIEW_PENDING · 원본 crop","코드-옵션-가격 묶음 대조","누락 · 오독 값 수정"]}},{"id":"candidate-assemble","group":"g-values","data":{"kind":"deterministic","label":"11. 결정론적 상품 후보 조립","sub":["상품-옵션-가격 관계","natural key · 중복","규칙 적용 범위","임의 카테시안 곱 금지"]}},{"id":"candidate-review","group":"g-values","data":{"kind":"gate","label":"12. 사람 확인 — 조립 관계 확정","sub":["REVIEW_PENDING · 후보 관계 대조","부분 적재 시 기존 상품 폐지 여부","유지 · supersede 범위 확정"]}},{"id":"auto-validate","group":"g-validate","data":{"kind":"verify","label":"13. 자동 검증 · TABLE_ONLY 골든 비교","sub":["누락 · 초과 · 중복","코드 · 가격 · 계산 규칙 차이","TABLE_ONLY golden JSON","결정론적 count · coverage 대사"]}},{"id":"finding-review","group":"g-validate","data":{"kind":"gate","label":"14. 사람 확인 — finding 처리","sub":["REVIEW_PENDING · finding 승인/반려","재처리 시작 지점 지정","사람 수정도 검증 우회 불가"]}},{"id":"staging-write","group":"g-validate","data":{"kind":"store","label":"15. price_import_candidates staging 적재","sub":["candidate + evidence + lineage","워커 쓰기 권한의 마지막 경계","운영 마스터 직접 쓰기 금지"]}},{"id":"diff-review","group":"g-activate","data":{"kind":"gate","label":"16. 사람 확인 — 운영 Diff 최종 승인","sub":["REVIEW_PENDING · 기존 vs 신규/변경/폐지","최종 활성화는 항상 사람 승인","정책에 따라 2인 승인"]}},{"id":"activate","group":"g-activate","data":{"kind":"activate","label":"17. 운영 활성화","sub":["승인 토큰을 가진 별도 로더만 실행","에디션 전환 · 발효일","ACTIVE 마스터 운영 소비"]}},{"id":"review-pending-state","group":"g-revision","data":{"kind":"gate","label":"REVIEW_PENDING — 사람 확인 대기","sub":["2 · 4 · 6 · 8 · 10 · 12 · 14 · 16 공통","정상 산출물 완료 후 검토 큐 진입","승인 · 정보 요청 · 재처리로 분기"]}},{"id":"needs-input","group":"g-revision","data":{"kind":"entry","label":"NEEDS_INPUT — 정보 부족","sub":["브랜드 · 에디션 · 통화 · 세금 미확정","부분 PDF 범위 · 문서 밖 판단 부족","추측하지 않고 입력 보강 대기"]}},{"id":"rework-required","group":"g-revision","data":{"kind":"failure","label":"REWORK_REQUIRED — 오류 수정 후 재처리","sub":["OCR 오독 · 영역 · 골격 · 값 · 관계 오류","finding 반려 · 최종 Diff 반려","수정 지점과 reason code 기록"]}},{"id":"artifact-invalidate","group":"g-revision","data":{"kind":"store","label":"하위 산출물 STALE 무효화","sub":["상위 수정 지점 아래 artifact만","승인 skeleton · dataset hash · 검증 실효","기존 revision과 감사 이력은 보존"]}},{"id":"new-revision","group":"g-revision","data":{"kind":"deterministic","label":"새 revision 생성 · 재처리","sub":["덮어쓰기 없이 correction lineage 추가","가장 가까운 올바른 단계로 복귀","하위 승인 게이트와 검증 다시 수행"]}},{"id":"return-point","group":"g-revision","data":{"kind":"model","label":"가장 가까운 기계 단계로 복귀","sub":["3 · 5 · 7 · 9 · 11 · 13 중 선택","수정 지점별 영향 범위만 재처리","완료 후 해당 사람 게이트 REVIEW_PENDING"]}}],"edges":[{"id":"e01","source":"pdf-intake","target":"scope-review","kind":"impl","tone":"entry"},{"id":"e02","source":"scope-review","target":"text-evidence","kind":"impl","tone":"gate"},{"id":"e03","source":"text-evidence","target":"text-review","kind":"impl","tone":"model"},{"id":"e04","source":"text-review","target":"region-discovery","kind":"impl","tone":"gate"},{"id":"e05","source":"region-discovery","target":"region-review","kind":"impl","tone":"model"},{"id":"e06","source":"region-review","target":"skeleton-extract","kind":"impl","tone":"gate"},{"id":"e07","source":"skeleton-extract","target":"skeleton-review","kind":"impl","tone":"deterministic"},{"id":"e08","source":"skeleton-review","target":"value-extract","kind":"impl","tone":"gate","label":"골격 고정"},{"id":"e09","source":"value-extract","target":"value-review","kind":"impl","tone":"model"},{"id":"e10","source":"value-review","target":"candidate-assemble","kind":"impl","tone":"gate"},{"id":"e11","source":"candidate-assemble","target":"candidate-review","kind":"impl","tone":"deterministic"},{"id":"e12","source":"candidate-review","target":"auto-validate","kind":"impl","tone":"gate"},{"id":"e13","source":"auto-validate","target":"finding-review","kind":"impl","tone":"verify"},{"id":"e14","source":"finding-review","target":"staging-write","kind":"impl","tone":"gate","label":"finding 확정"},{"id":"e15","source":"staging-write","target":"diff-review","kind":"impl","tone":"store","label":"별도 승인 경계"},{"id":"e16","source":"diff-review","target":"activate","kind":"impl","tone":"activate","label":"사람 최종 승인"},{"id":"x01","source":"scope-review","target":"review-pending-state","kind":"ref","tone":"gate","label":"모든 사람 게이트 공통"},{"id":"x02","source":"review-pending-state","target":"needs-input","kind":"impl","tone":"entry","label":"정보 부족"},{"id":"x03","source":"review-pending-state","target":"rework-required","kind":"impl","tone":"failure","label":"수정 · 반려"},{"id":"x09","source":"needs-input","target":"artifact-invalidate","kind":"impl","tone":"entry","label":"입력 보강"},{"id":"x10","source":"rework-required","target":"artifact-invalidate","kind":"impl","tone":"failure","label":"상위 값 수정"},{"id":"x11","source":"artifact-invalidate","target":"new-revision","kind":"impl","tone":"store","label":"영향 범위만"},{"id":"r01","source":"new-revision","target":"return-point","kind":"impl","tone":"model","label":"returnTo 지정"},{"id":"r02","source":"return-point","target":"review-pending-state","kind":"ref","tone":"gate","label":"재처리 완료 → 재검토"}]}'::jsonb);
INSERT INTO flow_document (project_slug,category_slug,slug,position,document) VALUES ('tns','pricelist','pricelist-overall',2,'{"slug":"pricelist-overall","title":"가격표 자동 적재 — 전체 흐름","description":"업로드 → 구조 판정 → 판독 → 조립 → 검증 → 위험도 게이트 → 활성화 → ACTIVE 마스터","caption":"가격표 자동 적재 전체 흐름 · 대문자 그룹 = 워커 배치 상태","direction":"TB","groupDirection":"LR","nodeWidth":250,"howToRead":["대문자 그룹 라벨은 워커의 배치 상태 이름입니다. 배치는 위에서 아래로 상태를 넘어가고, 한 상태 안에서는 왼쪽에서 오른쪽으로 처리됩니다.","브랜드 라우팅에서 KNOWN / CHANGED / UNKNOWN 이 갈라집니다. 신규·변경 구조는 전체 추출 전에 파일럿과 구조 카드 승인을 먼저 받습니다.","Tier 3 사람 수정은 검증 면제가 아닙니다 — staging 갱신 후 재검증을 거쳐 새 AUDIT-PASS 를 받고 게이트를 재판정합니다.","실패·반려는 전부 복구 루프의 원인 분류로 모이고, 원본/구조/판독/조립 중 가장 가까운 단계로만 되돌아갑니다."],"groups":[{"id":"g-read","label":"PROFILING · MAPPED — 문서를 읽고 지도를 만든다","kind":"entry"},{"id":"g-route","label":"ROUTED — KNOWN / CHANGED / UNKNOWN 분기","kind":"gate"},{"id":"g-onboard","label":"ONBOARDING — 전체 추출 전에 구조를 확정한다","kind":"activate"},{"id":"g-extract","label":"EXTRACTING — 의미 단위 정밀 추출","kind":"model"},{"id":"g-assemble","label":"ASSEMBLED — 결정론적 조립 → Staging","kind":"deterministic"},{"id":"g-verify","label":"VERIFYING — 기계 검증 + 독립 감사","kind":"verify"},{"id":"g-gate","label":"GATED — 위험도 티어 판정","kind":"gate"}],"nodes":[{"id":"upload","data":{"kind":"entry","label":"가격표 업로드","sub":["가격 담당자 · 브랜드 PDF/XLSX"]}},{"id":"batch","data":{"kind":"entry","label":"배치 생성","sub":["source_hash 멱등 · 에디션 후보","원본은 불변 보관"]}},{"id":"queue","data":{"kind":"store","label":"작업 큐","sub":["stage · attempt · lease","재시도 예산 · 부분 재개"]}},{"id":"profile","group":"g-read","data":{"kind":"deterministic","label":"프로파일링","sub":["렌더 · OCR · 단어 좌표","페이지 지문 · 인벤토리"]}},{"id":"docmap","group":"g-read","data":{"kind":"model","label":"AI 문서 지도","sub":["섹션 · 표 · 축 후보 판독","완결성은 코드가 되짚음"]}},{"id":"compare","group":"g-read","data":{"kind":"verify","label":"어댑터 · 구조 지문 비교","sub":["등록된 지문 ↔ 이번 지도","섹션 · 표별 구조 diff","브랜드 평균으로 뭉개지 않음"]}},{"id":"known","group":"g-route","data":{"kind":"activate","label":"KNOWN — 기존 계약 그대로","sub":["계약 · 불변식 일치","등록 contract 재사용"]}},{"id":"changed","group":"g-route","data":{"kind":"gate","label":"CHANGED — 변경 섹션 정찰","sub":["바뀐 섹션 · 표만 다시 읽음","나머지는 기존 계약 유지"]}},{"id":"unknown","group":"g-route","data":{"kind":"gate","label":"UNKNOWN — 신규 브랜드","sub":["신규 브랜드 · 신종 메커니즘","기존 스키마 억지 매핑 금지"]}},{"id":"card","group":"g-onboard","data":{"kind":"model","label":"구조 카드 + 기계 검증","sub":["모델 grain · 행축 / 열축 의미","마감 vs 가격 밴드 · 환산계수","net / PVP · VAT · 가격 메커니즘","후보는 AI, 완결성은 코드"]}},{"id":"pilot","group":"g-onboard","data":{"kind":"verify","label":"대표 파일럿","sub":["가장 복잡한 1개 섹션 먼저","원본과 코드 · 셀 · 배치 대사","충돌 0 · 누락 0 후 전수 확대"]}},{"id":"minhuman","group":"g-onboard","data":{"kind":"gate","label":"구조 카드 최소 승인","sub":["AI 가 근거 · 후보를 제안","사람은 예외만 확인","고객이 메타데이터를 쓰는 게 아님","전수 검토 아님 — 구조만 확정"]}},{"id":"adapterv","group":"g-onboard","data":{"kind":"activate","label":"Adapter v1 / vNext","sub":["detect · extract 계약 · 불변식","worked examples · fixtures","버전 고정 후 본선 합류"]}},{"id":"extract","group":"g-extract","data":{"kind":"model","label":"의미 단위 정밀 추출","sub":["표 · 제품 블록 · crop 단위","인쇄값 + 정규화값 + 근거 좌표"]}},{"id":"reread","group":"g-extract","data":{"kind":"gate","label":"재판독 · 승격 정책","sub":["API 오류 → 동일 shard 재시도","형식 오류 → schema repair 1회","판독 불명확 → crop 확대","구조 불일치 → 상위 모델 승격","같은 호출 반복은 승격이 아님"]}},{"id":"axis","group":"g-assemble","data":{"kind":"deterministic","label":"Axis Role 판정","sub":["SKU_IDENTITY / PRICE_SCOPE","CONFIGURATION / DISPLAY_ATTRIBUTE","판정 불가는 UNKNOWN 으로 남김","형상 · 길이 · 마감 = variant axis"]}},{"id":"combos","group":"g-assemble","data":{"kind":"deterministic","label":"유효 조합 Resolver","sub":["원본에 있거나 명시 허용된 조합만","옵션의 카테시안 곱 자동 생성 금지"]}},{"id":"build","group":"g-assemble","data":{"kind":"deterministic","label":"SKU · 가격 · 구성 조립","sub":["SKU Materializer","Price Rule Builder","밴드 · 할증 · 수량 티어 = 규칙","Configuration Builder"]}},{"id":"links","group":"g-assemble","data":{"kind":"deterministic","label":"품목 관계 확정","sub":["각주 · 병기 코드 · 도면 → 후보","필수 부속 · 포함 · 호환 · 대체","source / target / 방향 / 조건","evidence 없으면 채택하지 않음"]}},{"id":"staging","group":"g-assemble","data":{"kind":"deterministic","label":"Staging 후보","sub":["candidate + evidence + lineage","gate_status 미정","운영 마스터 직접 쓰기 없음"]}},{"id":"verify","group":"g-verify","data":{"kind":"verify","label":"V1~V9 검증","sub":["값 · 커버리지 · 값 오배치","표 전멸(whole-missing) 탐지"]}},{"id":"audit","group":"g-verify","data":{"kind":"model","label":"독립 의미 감사","sub":["추출과 다른 모델 · 공급자","신규 · 불일치 · 고위험 표만"]}},{"id":"auditpass","group":"g-verify","data":{"kind":"activate","label":"AUDIT-PASS + dataset_hash","sub":["verdict · findings · blind_spots","audited_by ≠ assembled_by","데이터 바뀌면 자동 실효"],"doc":"AUDIT-PASS"}},{"id":"gate","group":"g-gate","data":{"kind":"gate","label":"위험도 게이트","sub":["Tier 1 / 2 / 3 판정","최소 영향 범위 단위로"]}},{"id":"tier1","group":"g-gate","data":{"kind":"activate","label":"Tier 1 — 자동 확정","sub":["KNOWN 구조 · 전 검증 통과","새 가격 규칙 없음"]}},{"id":"tier2","group":"g-gate","data":{"kind":"verify","label":"Tier 2 — 반영 후 감시","sub":["구조 · 가격은 확실","저위험 속성만 사후 샘플"]}},{"id":"tier3","group":"g-gate","data":{"kind":"gate","label":"Tier 3 — 격리","sub":["신규 구조 · 교차 불일치","문서 밖 값 · 판독 불가","직접 활성화 불가"]}},{"id":"review","data":{"kind":"entry","label":"사람 검토 · 수정","sub":["근거 뷰어 · 에디션 Diff","승인자 분리 · 전건 감사 로그","UNKNOWN 을 확정 입력으로 바꾸는 행위"]}},{"id":"rcls","data":{"kind":"failure","label":"실패 · 반려 원인 분류","sub":["표준 reason code 로만 기록","기술 / 원본·OCR / 구조 / 조립","검증 / 의미 감사 / 사람 반려","자유 오류 메시지로는 자동 복구 불가"]}},{"id":"rplan","data":{"kind":"gate","label":"복구 계획","sub":["returnTo · strategy · maxAttempts","재시도(같은 입력) ≠ 재처리(방법 변경)","AI 는 제안, 복귀 단계는 코드 정책","같은 호출 무한 반복은 복구가 아님"]}},{"id":"rinval","data":{"kind":"store","label":"하위 산출물 무효화","sub":["산출물 DAG 아래는 전부 STALE","부분 범위면 그 scope 만","dataset_hash · AUDIT-PASS 자동 실효"]}},{"id":"recheck","data":{"kind":"verify","label":"영향 범위 재조립 · 재검증","sub":["덮어쓰지 않고 candidate revision 추가","Axis Role · grain 재판정 포함","영향 범위만 다시 조립 · 관련 V 재실행","새 AUDIT-PASS 없으면 활성화 불가"]}},{"id":"hold","data":{"kind":"failure","label":"미해결 상태 — 원인 명시","sub":["NEEDS_INPUT — 문서 밖 값 · 사용자 판단","NEEDS_SOURCE — 원천자료 자체가 없음","REJECTED — 잘못된 후보로 확정","추측으로 채우지 않는다"]}},{"id":"dlq","data":{"kind":"failure","label":"기술 실패 · DLQ","sub":["복구 시도 · 예산 한도까지 소진한 것만","PROVIDER · STORAGE · WORKER 오류","의미 불확실은 격리, 구조 변경은 재라우팅"]}},{"id":"donecheck","data":{"kind":"verify","label":"배치 완료 판정","sub":["전 페이지 분류 · 표는 추출 또는 명시 제외","커버리지 게이트 · identity 충돌 0","근거 없는 자동 확정 0 · 검증 실패 scope 0","UNKNOWN 0 또는 NEEDS_SOURCE 로 명시","활성화 후 카운트 대사까지 통과"]}},{"id":"loader","data":{"kind":"activate","label":"제한된 활성화 로더","sub":["Tier 1 → 자동 활성화","Tier 2 → 활성화 + 감시 플래그","AUDIT-PASS + dataset_hash 대조","신규 브랜드 첫 배치는 별도 승인"]}},{"id":"master","data":{"kind":"activate","label":"ACTIVE 가격 마스터","sub":["에디션 전환 · supersedes · 발효일"]}},{"id":"consume","data":{"kind":"activate","label":"운영 소비","sub":["견적 · 발주 · 원가 계산","격리분은 사용 차단"]}},{"id":"adapter","data":{"kind":"activate","label":"브랜드 어댑터 레지스트리","sub":["detect · extract 계약 · 불변식","배치마다 버전 고정"]}},{"id":"models","data":{"kind":"model","label":"모델 계층","sub":["저비용: 지도 · 분류","정밀: 표 · 축 판독","고난도: 교차 감사"]}},{"id":"store","data":{"kind":"store","label":"저장소","sub":["원본 · source_hash","페이지 이미지 · OCR · profile","document-map · crop · 원응답","dataset · verify · AUDIT-PASS","gate · 승인 · 전환 이벤트"]}},{"id":"observ","data":{"kind":"store","label":"관측","sub":["로그 · 메트릭 · 트레이스","단계별 비용 · 자동 처리율","격리율 · 알림"]}},{"id":"boundary","data":{"kind":"gate","label":"강제 통제 경계","sub":["워커 계정은 staging 까지만","ACTIVE 쓰기는 활성화 로더만"]}},{"id":"learn","data":{"kind":"activate","label":"확정 사례 분류","sub":["브랜드 고유인가 범용 결함인가","이걸 안 나누면 전용 파서로 굳는다"]}},{"id":"corefix","data":{"kind":"deterministic","label":"Pipeline Core · 공통 스키마","sub":["다열 표 헤더 시프트 같은 범용 결함","관계 유형 자체가 부족한 경우","전 브랜드 회귀 테스트 필수"]}},{"id":"golden","data":{"kind":"verify","label":"골든 벤치마크 · CI","sub":["과거 결함 회귀 고정","모델 교체 전후 동일 평가"]}}],"edges":[{"id":"e1","source":"upload","target":"batch","kind":"impl","tone":"entry"},{"id":"e2","source":"batch","target":"queue","kind":"impl","tone":"entry"},{"id":"e3","source":"queue","target":"profile","kind":"impl","tone":"store","label":"비동기 소비"},{"id":"e4","source":"profile","target":"docmap","kind":"impl","tone":"deterministic"},{"id":"e5","source":"docmap","target":"compare","kind":"impl","tone":"model"},{"id":"e6","source":"adapter","target":"compare","kind":"ref","tone":"activate","label":"계약 · 불변식"},{"id":"e7","source":"compare","target":"known","kind":"impl","tone":"activate","label":"일치"},{"id":"e8","source":"compare","target":"changed","kind":"impl","tone":"gate","label":"구조 변경"},{"id":"e9","source":"compare","target":"unknown","kind":"impl","tone":"gate","label":"미등록"},{"id":"e10","source":"unknown","target":"card","kind":"impl","tone":"gate"},{"id":"e11","source":"changed","target":"pilot","kind":"impl","tone":"gate","label":"변경분만"},{"id":"e12","source":"card","target":"pilot","kind":"impl","tone":"model"},{"id":"e13","source":"pilot","target":"minhuman","kind":"impl","tone":"gate","label":"신규 구조"},{"id":"e14","source":"minhuman","target":"adapterv","kind":"impl","tone":"activate","label":"구조 확정"},{"id":"e15","source":"pilot","target":"adapterv","kind":"impl","tone":"activate","label":"CHANGED"},{"id":"e16","source":"known","target":"extract","kind":"impl","tone":"model","label":"기존 계약 추출"},{"id":"e17","source":"adapterv","target":"extract","kind":"impl","tone":"model","label":"계약 고정 → 전체 추출"},{"id":"e18","source":"extract","target":"reread","kind":"impl","tone":"model","label":"실패 · 불명확"},{"id":"e19","source":"reread","target":"extract","kind":"ref","tone":"gate","label":"문맥 · 모델 승격"},{"id":"e20","source":"reread","target":"rcls","kind":"impl","tone":"failure","label":"재시도로 안 되는 것"},{"id":"e22","source":"extract","target":"axis","kind":"impl","tone":"deterministic","label":"page JSON + 근거"},{"id":"e23","source":"axis","target":"combos","kind":"impl","tone":"deterministic"},{"id":"e24","source":"combos","target":"build","kind":"impl","tone":"deterministic"},{"id":"e25","source":"axis","target":"links","kind":"impl","tone":"deterministic","label":"SKU 축이 아닌 것"},{"id":"e26","source":"build","target":"staging","kind":"impl","tone":"deterministic"},{"id":"e27","source":"links","target":"staging","kind":"impl","tone":"deterministic","label":"item_links 후보"},{"id":"e28","source":"staging","target":"verify","kind":"impl","tone":"verify"},{"id":"e29","source":"verify","target":"audit","kind":"impl","tone":"model","label":"고위험 표만"},{"id":"e30","source":"audit","target":"auditpass","kind":"impl","tone":"activate"},{"id":"e31","source":"auditpass","target":"gate","kind":"impl","tone":"gate"},{"id":"e32","source":"gate","target":"tier1","kind":"impl","tone":"activate","label":"Tier 1"},{"id":"e33","source":"gate","target":"tier2","kind":"impl","tone":"verify","label":"Tier 2"},{"id":"e34","source":"gate","target":"tier3","kind":"impl","tone":"gate","label":"Tier 3"},{"id":"e35","source":"tier3","target":"review","kind":"impl","tone":"gate"},{"id":"e36","source":"review","target":"rcls","kind":"impl","tone":"gate","label":"수정값 · 반려 사유"},{"id":"v1","source":"verify","target":"rcls","kind":"impl","tone":"failure","label":"검증 실패 scope"},{"id":"v2","source":"auditpass","target":"rcls","kind":"impl","tone":"failure","label":"감사 반려"},{"id":"v3","source":"loader","target":"rcls","kind":"impl","tone":"failure","label":"활성화 실패"},{"id":"v4","source":"rcls","target":"rplan","kind":"impl","tone":"failure"},{"id":"v5","source":"rplan","target":"rinval","kind":"impl","tone":"gate"},{"id":"v6","source":"rinval","target":"recheck","kind":"impl","tone":"verify","label":"재조립 · 재검증만"},{"id":"v7","source":"recheck","target":"gate","kind":"impl","tone":"verify","label":"새 AUDIT-PASS → 재판정"},{"id":"v8","source":"rinval","target":"profile","kind":"ref","tone":"deterministic","label":"원본 · OCR 오류"},{"id":"v9","source":"rinval","target":"changed","kind":"ref","tone":"gate","label":"CONTRACT_MISMATCH"},{"id":"v10","source":"rinval","target":"extract","kind":"ref","tone":"model","label":"판독 · 열 오류"},{"id":"v12","source":"rplan","target":"dlq","kind":"impl","tone":"failure","label":"시도 · 예산 한도 초과"},{"id":"v13","source":"rplan","target":"hold","kind":"impl","tone":"failure","label":"사람 · 원천자료 필요"},{"id":"e39","source":"tier1","target":"loader","kind":"impl","tone":"activate","label":"자동"},{"id":"e40","source":"tier2","target":"loader","kind":"impl","tone":"verify","label":"감시 플래그"},{"id":"e41","source":"loader","target":"master","kind":"impl","tone":"activate"},{"id":"e42","source":"master","target":"consume","kind":"impl","tone":"activate"},{"id":"e43","source":"master","target":"donecheck","kind":"impl","tone":"verify","label":"활성화 후 대사"},{"id":"e44","source":"donecheck","target":"hold","kind":"impl","tone":"failure","label":"미해결 원인 명시"},{"id":"s1","source":"models","target":"docmap","kind":"ref","tone":"model","label":"저비용"},{"id":"s2","source":"models","target":"extract","kind":"ref","tone":"model","label":"정밀"},{"id":"s3","source":"models","target":"audit","kind":"ref","tone":"model","label":"교차 공급자"},{"id":"s4","source":"staging","target":"store","kind":"impl","tone":"store","label":"후보 · 근거 · lineage"},{"id":"s5","source":"store","target":"review","kind":"ref","tone":"store","label":"근거 조회"},{"id":"s6","source":"gate","target":"observ","kind":"impl","tone":"store","label":"자동 처리율 · 격리율"},{"id":"s7","source":"models","target":"observ","kind":"ref","tone":"store","label":"호출 · 비용"},{"id":"s8","source":"boundary","target":"staging","kind":"ref","tone":"gate","label":"staging 까지만"},{"id":"s9","source":"boundary","target":"loader","kind":"ref","tone":"gate","label":"ACTIVE 쓰기 독점"},{"id":"s10","source":"review","target":"learn","kind":"impl","tone":"activate","label":"확정 사례"},{"id":"s11","source":"learn","target":"adapter","kind":"impl","tone":"activate","label":"브랜드 고유 → vNext"},{"id":"s12","source":"learn","target":"corefix","kind":"impl","tone":"deterministic","label":"범용 결함"},{"id":"s13","source":"corefix","target":"golden","kind":"impl","tone":"verify","label":"전 브랜드 회귀"},{"id":"s14","source":"observ","target":"golden","kind":"ref","tone":"verify","label":"지표 하락 케이스"},{"id":"s15","source":"golden","target":"adapter","kind":"ref","tone":"activate","label":"회귀 통과분만 효력"},{"id":"s16","source":"adapterv","target":"adapter","kind":"ref","tone":"activate","label":"버전 고정 → 다음 배치"}]}'::jsonb);
INSERT INTO flow_document (project_slug,category_slug,slug,position,document) VALUES ('tns','pricelist','pricelist-worker',3,'{"slug":"pricelist-worker","title":"가격표 워커 상세 — apps/pricelist-worker","description":"체크포인트 기반 배치 실행 · 의미 단위 추출 · scope 별 감사 · 격리 검토와 재검증","caption":"가격표 워커 상세","direction":"TB","groupDirection":"LR","nodeWidth":250,"howToRead":["그룹 라벨이 곧 배치 상태 머신입니다. 방 하나가 상태 하나, 방 안 박스는 그 상태의 실제 처리 순서입니다.","본선에 속하지 않는 실행 통제·저장·통제 경계·모델 정책·평가는 본선 옆 라인으로 빠져 있습니다.","사람 화면은 둘로 분리되어 있습니다 — 온보딩 구조 확인(어댑터 학습)과 격리 항목 검토(staging 수정)는 다른 업무입니다.","RECOVERY 그룹에서 나가는 점선 넷(재렌더·부분 온보딩·재판독·조립 재판정)이 원인별 복귀 지점입니다. 사람 반려도 DLQ 가 아니라 이 복구 루프로 들어갑니다."],"groups":[{"id":"g-run","label":"실행 통제 — 큐 lease · 체크포인트 · 순방향 전이만","kind":"store"},{"id":"g-read","label":"RECEIVED → PROFILING → MAPPED — 문서를 읽고 지도를 만든다","kind":"entry"},{"id":"g-route","label":"ROUTED — 브랜드 구조를 어댑터 계약과 대조","kind":"gate"},{"id":"g-onboard","label":"ONBOARDING — 신규·변경 브랜드. 끝나면 현재 배치 본선으로 돌아온다","kind":"activate"},{"id":"g-extract","label":"EXTRACTING — 의미 단위로 잘라 모델에 묻는다","kind":"model"},{"id":"g-assemble","label":"ASSEMBLED — 모델 출력을 코드가 결정론적으로 조립","kind":"deterministic"},{"id":"g-verify","label":"VERIFYING — V1~V9 기계 검증 + 다른 모델의 독립 감사","kind":"verify"},{"id":"g-gate","label":"GATED — scope 별 위험도 티어 판정 · 최소 영향 범위","kind":"gate"},{"id":"g-review","label":"격리 검토 · 재검증 — 사람이 확정 입력을 넣는 구간","kind":"entry"}],"nodes":[{"id":"resume","group":"g-run","data":{"kind":"store","label":"부분 재개 · 캐시","sub":["source/page/crop/prompt/model hash","성공 shard 재호출 금지","모델 바뀌면 영향 캐시만 무효화"]}},{"id":"orchestrator","group":"g-run","data":{"kind":"store","label":"Orchestrator","sub":["queue lease · heartbeat · dispatch","checkpoint · retry budget · timeout","idempotency key"]}},{"id":"artifact-contract","group":"g-run","data":{"kind":"store","label":"단계 산출물 계약","sub":["profile → document-map → plan","pages/*.json → dataset → verify → gate","리포트: pass·counts·hash·blind_spots"]}},{"id":"recorder","group":"g-run","data":{"kind":"store","label":"Artifact Recorder","sub":["단계 완료마다 입력 · 출력 기록","prompt · adapter · model version","source / page / crop hash","저장소로 가는 단일 창구"]}},{"id":"state-guard","group":"g-run","data":{"kind":"gate","label":"DB 상태 머신 · 권한","sub":["순방향 전이만 · 산출물 없으면 거부","evidence 없는 AUTO 후보 금지","워커 계정은 ACTIVE 쓰기 불가"]}},{"id":"ingest","group":"g-read","data":{"kind":"entry","label":"Source Ingest","sub":["MIME · 암호화 · 손상 검사","source_hash · 에디션 후보","원본은 Object Storage 불변 보관"]}},{"id":"render","group":"g-read","data":{"kind":"deterministic","label":"Render · OCR","sub":["내장 텍스트 우선","250~300 DPI 렌더 · 회전 보정","단어 bbox · 텍스트 밀도"]}},{"id":"finger","group":"g-read","data":{"kind":"deterministic","label":"Page Fingerprint","sub":["헤더·푸터·인쇄번호 offset","코드/숫자 밀도 · 이미지 비율","레이아웃 임베딩 · 클러스터"]}},{"id":"mapmodel","group":"g-read","data":{"kind":"model","label":"Document Map (AI)","sub":["INDEX/PRODUCT/RULE/SPEC/DIVIDER","섹션 경계 · 연속표 · 제품 블록","행축/열축 후보 · 판독 우선순위","클러스터 대표 · 이상 페이지 우선"]}},{"id":"mapverify","group":"g-read","data":{"kind":"verify","label":"Map 기계 검증","sub":["전 페이지 정확히 1개 분류","목차 ↔ 반복 헤더 ↔ 실제 페이지 대사","미분류·중복 소속·offset 불일치 차단","지도는 AI가, 완결성은 코드가 판정"]}},{"id":"compare","group":"g-route","data":{"kind":"verify","label":"Structure Comparator","sub":["신규 지도 ↔ 등록된 지문 비교","섹션/표별 유사도","축·밴드·규칙·코드 문법 diff","브랜드 평균으로 뭉개지 않음"]}},{"id":"route-known","group":"g-route","data":{"kind":"activate","label":"KNOWN — 본선 그대로","sub":["계약과 불변식 일치","기존 extraction contract 재사용","경량·고처리량 모델"]}},{"id":"route-new","group":"g-route","data":{"kind":"gate","label":"CHANGED · UNKNOWN — 온보딩 필요","sub":["CHANGED: 변경된 섹션·표만 정찰","UNKNOWN: 신규 브랜드·신규 메커니즘","기존 스키마에 억지 매핑 금지"]}},{"id":"discover","group":"g-onboard","data":{"kind":"model","label":"구조 카드 자동 생성","sub":["목차 · 섹션 · 가격표 블록","코드 문법 · 행/열축 · 마감/밴드","통화 · VAT · 가격 메커니즘","근거 · 반례 · UNKNOWN 포함"]}},{"id":"pilot","group":"g-onboard","data":{"kind":"verify","label":"대표 파일럿","sub":["가장 복잡한 1개 섹션 먼저","골든/원본과 코드·셀·배치 대사","충돌 0 · 누락 0 후 전수 확대"]}},{"id":"human","group":"g-onboard","data":{"kind":"gate","label":"온보딩 구조 확인","sub":["모델 grain · 행축 / 열축 의미","브랜드 고유 라벨 · 문서 밖 계수","net/PVP · VAT · 신규 메커니즘","구조만 확정 — 값 정정은 하지 않음"]}},{"id":"agentrole","group":"g-onboard","data":{"kind":"model","label":"Codex / Claude Code","sub":["실패 리포트 기반 어댑터·테스트 구현","반복 UNKNOWN 을 규칙으로","매 배치 실행·자기 승인은 금지"]}},{"id":"adapterv","group":"g-onboard","data":{"kind":"activate","label":"Adapter vNext","sub":["detect/map/extract/normalize/verify","worked examples · invariants","현재 배치에 adapter_version 고정","Registry 등록은 다음 배치용"]}},{"id":"planner","group":"g-extract","data":{"kind":"deterministic","label":"Extraction Planner","sub":["독립표 = crop","연속표 = 앞뒤 1~2페이지","제품명+도면+표 = 제품 블록","expected schema · max attempts"]}},{"id":"batcher","group":"g-extract","data":{"kind":"store","label":"Shard · Batch Scheduler","sub":["page/table/crop 독립 job","동시성 · rate limit · quota","공유 prompt · adapter cache","customId 로 결과 재결합"]}},{"id":"modelrouter","group":"g-extract","data":{"kind":"model","label":"Model Router","sub":["저비용: 분류·단순표","중급: 기본 구조·표","고급: 난항·UNKNOWN","교차 모델: 고위험 감사"]}},{"id":"contract","group":"g-extract","data":{"kind":"model","label":"Extraction Contract","sub":["printedValue / normalizedValue","page·table·cell bbox evidence","rowAxes/columnAxes/headers/cells","schemaMismatch 는 1급 결과"]}},{"id":"resultcheck","group":"g-extract","data":{"kind":"verify","label":"즉시 결과 검사","sub":["JSON Schema · 필수 근거","헤더 수 ↔ 셀 수","중복 · 빈 표 · 잘린 출력","모델 confidence 로 승인 금지"]}},{"id":"escalate","group":"g-extract","data":{"kind":"gate","label":"선택 재판독 · 실패 분류","sub":["불명확 셀 = crop 확대","표 구조 오류 = 표 전체 · 상위 모델","INVALID_MODEL_OUTPUT → repair 1회","CONTRACT_MISMATCH → 재라우팅","PROVIDER / BUDGET 소진 → DLQ"]}},{"id":"normalize","group":"g-assemble","data":{"kind":"deterministic","label":"Normalizer","sub":["코드 · 수치 · 통화 · 단위","브랜드 라벨 사전","인쇄값은 그대로 보존","문서 밖 값은 UNKNOWN"]}},{"id":"axisrole","group":"g-assemble","data":{"kind":"deterministic","label":"Axis Role Classifier","sub":["SKU_IDENTITY / PRICE_SCOPE","CONFIGURATION / DISPLAY_ATTRIBUTE","판정 불가는 UNKNOWN 으로 남김","모든 옵션을 SKU 로 만들지 않는다"]}},{"id":"combos","group":"g-assemble","data":{"kind":"deterministic","label":"Valid Combination Resolver","sub":["원본에 있거나 명시 허용된 조합만","카테시안 곱으로 임의 생성 금지","스코프 전개 · 리졸버 유일해"]}},{"id":"assemble","group":"g-assemble","data":{"kind":"deterministic","label":"Catalog Assembler","sub":["종류 → 컬렉션 → 모델 → SKU","SKU Materializer","Price Scope · Rule Builder","Configuration Builder"]}},{"id":"relbuild","group":"g-assemble","data":{"kind":"deterministic","label":"Item Relationship Builder","sub":["다른 품목의 필수·포함·호환·대체","같은 모델의 변형은 관계가 아님","밴드 · 할증은 가격 관계","source/target/방향/조건/evidence 필수"]}},{"id":"identity","group":"g-assemble","data":{"kind":"verify","label":"Identity · Relation Conflict","sub":["SKU identity 유니크 · NULLS NOT DISTINCT","같은 코드의 모델 scope 보존","축 충돌 · 중복 · orphan 차단","관계 대상 없음 · 순환 관계 차단"]}},{"id":"staging","group":"g-assemble","data":{"kind":"deterministic","label":"Staging Writer","sub":["candidate + evidence + lineage","gate_status 미정","batch transaction","운영 마스터 직접 쓰기 없음"]}},{"id":"diff","group":"g-assemble","data":{"kind":"verify","label":"Edition Diff","sub":["신규 · 폐지 SKU","가격 · 규칙 · 밴드 변경","이전 ACTIVE 를 비교 오라클로"]}},{"id":"v1v3","group":"g-verify","data":{"kind":"verify","label":"V1~V3 — 값 · 카운트 · 결정성","sub":["워크드예제 값 재현","목차 · 코드 · 행 · 셀 수 대사","스코프 전개 · 리졸버 유일해","사각: 의미상 잘못된 모델 grain"]}},{"id":"v4v5","group":"g-verify","data":{"kind":"verify","label":"V4~V5 — Diff · 교차 출처","sub":["이전 에디션 구조 · 가격 diff","PDF text ↔ OCR ↔ Vision ↔ XLSX","사각: 여러 경로가 같이 틀린 경우"]}},{"id":"v6v7","group":"g-verify","data":{"kind":"verify","label":"V6~V7 — 커버리지 · 변형","sub":["전 페이지 코드 vs 조립분","코드별 원본 가격셀 집합 대사","사각: 값집합 같고 위치만 바뀐 경우"]}},{"id":"v8v9","group":"g-verify","data":{"kind":"verify","label":"V8~V9 — 오배치 · Whole-missing","sub":["열 이동 · 가격==사이즈 · 단조성","페이지 인벤토리 vs staging","표 · 디자인 전멸 탐지"]}},{"id":"semantic-audit","group":"g-verify","data":{"kind":"model","label":"독립 의미 감사","sub":["추출과 다른 모델·프롬프트·공급자","신규 / 불일치 / 고위험 표만","규칙 scope · 축 · grain 을 공격","감사자는 staging 읽기 전용"]}},{"id":"auditpass","group":"g-verify","data":{"kind":"activate","label":"AUDIT 결과 — scope 단위","sub":["passedScopes / quarantinedScopes","failedScopes / blindSpots","dataset_hash · audited_by ≠ assembled_by","배치 하나에 PASS 하나를 주지 않는다"],"doc":"AUDIT-PASS"}},{"id":"tier1","group":"g-gate","data":{"kind":"activate","label":"Tier 1 — AUTO_CONFIRM","sub":["KNOWN 구조 · 교차 일치","V1~V9 PASS · 새 규칙 없음"]}},{"id":"tier2","group":"g-gate","data":{"kind":"verify","label":"Tier 2 — MONITOR","sub":["구조 · 가격은 확실","저위험 속성만 사후 샘플"]}},{"id":"tier3","group":"g-gate","data":{"kind":"gate","label":"Tier 3 — QUARANTINE","sub":["신규 구조 · 열 의미 · 가격 규칙","문서 밖 값 · 교차 불일치","DB 보존, ACTIVE 사용 금지"]}},{"id":"impact","group":"g-gate","data":{"kind":"gate","label":"최소 영향 범위","sub":["셀 오류 → 셀 / SKU","열 헤더 → 열 전체","표 구조 → 모델 · 섹션 구조 → 섹션","정상 범위는 계속 자동 처리"]}},{"id":"qreview","group":"g-review","data":{"kind":"entry","label":"격리 항목 검토","sub":["셀 수정 · 관계 승인 · UNKNOWN 확정","재판독 요청 · 원천 부족 판정","근거 뷰어 · 전건 감사 로그","값 정정을 브랜드 규칙으로 학습 금지"]}},{"id":"revise","group":"g-review","data":{"kind":"verify","label":"Revised Candidate · 재검증","sub":["덮어쓰지 않고 revision 추가","rev1 AI 추출 · rev2 재판독 · rev3 사람 확정","Axis Role · grain 재판정 포함","영향 범위만 재조립 · 관련 V 재실행","새 dataset_hash → 새 AUDIT-PASS"]}},{"id":"holdstate","data":{"kind":"failure","label":"미해결 상태 — 원인 명시","sub":["NEEDS_INPUT — 문서 밖 값 · 사용자 판단","NEEDS_SOURCE — 원천자료 자체가 없음","REJECTED — 잘못된 후보로 확정","추측으로 채우지 않는다"]}},{"id":"failcls","data":{"kind":"failure","label":"Failure Classifier","sub":["기술: PROVIDER_TIMEOUT · RATE_LIMITED","원본: SOURCE_CORRUPTED · OCR_LOW_QUALITY","구조: CONTRACT_MISMATCH · COLUMN_ALIGNMENT","조립: SKU_IDENTITY_CONFLICT · GRAIN_AMBIGUOUS","검증: WHOLE_TABLE_MISSING · AUDIT_REJECTED","사람: WRONG_AXIS_ROLE · SOURCE_REQUIRED"]}},{"id":"rplanner","data":{"kind":"gate","label":"Recovery Planner","sub":["reason code → returnTo · strategy","영향 범위 산정 · maxAttempts · 비용 한도","재시도(같은 입력) ≠ 재처리(방법 변경)","사람 입력 필요 여부 · 재검증 범위 결정","AI 는 제안, 허용 전략은 코드 정책"]}},{"id":"invalidator","data":{"kind":"store","label":"Artifact Invalidator","sub":["source → profile → map → extraction","→ assembly → verify → audit → gate","상위가 바뀌면 그 아래는 전부 STALE","부분 범위면 그 scope 만 무효화","REWORK_REQUIRED → REPROCESSING"]}},{"id":"registry-read","data":{"kind":"activate","label":"Adapter Registry","sub":["브랜드 detect rules","layout fingerprints","extraction contracts · invariants","버전별 효력 · 변경 이력"]}},{"id":"providerpolicy","data":{"kind":"store","label":"모델 Provider 정책","sub":["모델 ID · prompt version 고정","ZDR · 보존기간 · 지역 정책","키 · quota · rate limit · 비용 상한","릴리스 게이트 통과분만 교체"]}},{"id":"stores","data":{"kind":"store","label":"저장소 · lineage","sub":["PostgreSQL: 상태·staging·검증·승인","Object Storage: 원본·페이지·crop·원응답","Queue: 단계·attempt·lease·DLQ","prompt/adapter/model version 으로 재현"]}},{"id":"boundary","data":{"kind":"gate","label":"통제 · 감사 경계","sub":["워커 DB 역할은 staging/report 까지","상태 전이·승인·재처리 append-only","source_hash 멱등 · reload 는 명시 승인"]}},{"id":"fail","data":{"kind":"failure","label":"FAILED / DLQ — 복구 한도 소진","sub":["복구 전략 · 시도 · 예산을 다 쓴 것만","PROVIDER · STORAGE · WORKER · BUDGET","CONTRACT_MISMATCH · 사람 반려는 여기가 아님","마지막 안전 checkpoint 유지"]}},{"id":"donecheck","data":{"kind":"verify","label":"완료 판정 기준","sub":["전 페이지 분류 · 표는 추출 또는 명시 제외","코드·가격·변형·관계 커버리지 게이트 통과","identity 충돌 0 · 근거 없는 자동 확정 0","검증 실패 scope 0 · UNKNOWN 0 또는 명시 보류","dataset_hash 기준 AUDIT-PASS 존재","활성화 트랜잭션 사후 카운트 대사 통과"]}},{"id":"completed","data":{"kind":"activate","label":"배치 종료 — 상태 구분","sub":["COMPLETED — 전 범위 정상 종료","PARTIALLY_COMPLETED — 격리 잔여","AWAITING_REVIEW — 활성화분 없음","후보 집계: ACTIVE / MONITOR / QUARANTINED"]}},{"id":"activation","data":{"kind":"activate","label":"제한된 활성화 로더 — 워커 권한 밖","sub":["Tier 1 + AUDIT-PASS + hash → 자동","Tier 2 → 활성화 + MONITOR 플래그","신규 브랜드 · 구조 변경 → 사용자 승인","Tier 3 → 직접 활성화 금지"]}},{"id":"feedback","data":{"kind":"activate","label":"확정 사례 분류","sub":["브랜드 고유 판정 → 사전 · 워크드예제","범용 결함 → 코어 · 공통 스키마","이걸 안 나누면 전용 파서로 굳는다"]}},{"id":"corefix","data":{"kind":"deterministic","label":"Pipeline Core · 공통 스키마","sub":["다열 표 헤더 시프트 같은 범용 결함","관계 유형 자체가 부족한 경우","전 브랜드 회귀 테스트 필수"]}},{"id":"metrics","data":{"kind":"store","label":"품질 · 비용 지표","sub":["표 발견 recall · 코드/가격 정확도","변형 recall · 열 이동 · whole-missing","자동 처리율 · 자동 확정 정확도","격리율 · 페이지당 비용/시간"]}},{"id":"golden","data":{"kind":"verify","label":"골든 벤치마크 · 릴리스 게이트","sub":["Inbani 원본 + 검증셋 + 실패 페이지","2열 시프트 · 형상 6/9 누락 · 전멸","모델/프롬프트 전후 동일 평가셋","정확도 하락 · 전멸 1건이면 배포 차단"]}}],"edges":[{"id":"r1","source":"resume","target":"orchestrator","kind":"ref","tone":"store"},{"id":"r2","source":"orchestrator","target":"artifact-contract","kind":"impl","tone":"store","label":"단계마다 산출물"},{"id":"r3","source":"artifact-contract","target":"recorder","kind":"impl","tone":"store","label":"입력·출력·hash 기록"},{"id":"r3b","source":"recorder","target":"state-guard","kind":"impl","tone":"store","label":"필수 산출물 검사"},{"id":"r4","source":"state-guard","target":"orchestrator","kind":"ref","tone":"gate"},{"id":"r5","source":"orchestrator","target":"ingest","kind":"impl","tone":"store","label":"큐 lease → 단계 dispatch"},{"id":"r6","source":"recorder","target":"stores","kind":"impl","tone":"store","label":"모든 단계 artifact"},{"id":"b1","source":"ingest","target":"render","kind":"impl","tone":"entry"},{"id":"b2","source":"render","target":"finger","kind":"impl","tone":"deterministic"},{"id":"b3","source":"render","target":"mapmodel","kind":"impl","tone":"model","label":"페이지 이미지 · 텍스트"},{"id":"b3b","source":"finger","target":"mapmodel","kind":"impl","tone":"deterministic","label":"클러스터 · 대표 페이지"},{"id":"b4","source":"finger","target":"mapverify","kind":"impl","tone":"deterministic","label":"페이지 사실"},{"id":"b5","source":"mapmodel","target":"mapverify","kind":"impl","tone":"model","label":"페이지별 분류"},{"id":"c0","source":"mapverify","target":"compare","kind":"impl","tone":"gate","label":"Document Map"},{"id":"c1","source":"registry-read","target":"compare","kind":"ref","tone":"activate"