ditpass","target":"failcls","kind":"impl","tone":"failure","label":"failedScopes"},{"id":"g4","source":"tier3","target":"impact","kind":"impl","tone":"gate","label":"격리 범위 산정"},{"id":"k1","source":"impact","target":"qreview","kind":"impl","tone":"gate","label":"격리분만 사람 검토"},{"id":"k2","source":"qreview","target":"revise","kind":"impl","tone":"verify","label":"값 확정 · 승인"},{"id":"k3","source":"qreview","target":"failcls","kind":"impl","tone":"failure","label":"반려 사유 · 재판독 요청"},{"id":"k5","source":"revise","target":"v1v3","kind":"ref","tone":"verify","label":"관련 V 재실행 → 재판정"},{"id":"w1","source":"activation","target":"failcls","kind":"impl","tone":"failure","label":"활성화 실패"},{"id":"w2","source":"failcls","target":"rplanner","kind":"impl","tone":"failure","label":"reason code"},{"id":"w3","source":"rplanner","target":"invalidator","kind":"impl","tone":"gate","label":"복구 계획"},{"id":"w4","source":"invalidator","target":"render","kind":"ref","tone":"deterministic","label":"원본 · OCR → 재렌더"},{"id":"w5","source":"invalidator","target":"route-new","kind":"ref","tone":"gate","label":"CONTRACT_MISMATCH → 부분 온보딩"},{"id":"w6","source":"invalidator","target":"planner","kind":"ref","tone":"model","label":"재판독 · crop 확대 · 모델 승격"},{"id":"w8","source":"invalidator","target":"v1v3","kind":"ref","tone":"verify","label":"재검증만 필요한 경우"},{"id":"w9","source":"rplanner","target":"fail","kind":"impl","tone":"failure","label":"시도 · 예산 한도 초과"},{"id":"w10","source":"rplanner","target":"holdstate","kind":"impl","tone":"failure","label":"사람 · 원천자료 필요"},{"id":"t1","source":"tier1","target":"completed","kind":"impl","tone":"activate","label":"자동 확정"},{"id":"t2","source":"tier2","target":"completed","kind":"impl","tone":"verify","label":"반영 후 감시"},{"id":"t3","source":"impact","target":"completed","kind":"impl","tone":"gate","label":"정상 범위만 계속"},{"id":"t5","source":"completed","target":"activation","kind":"impl","tone":"activate","label":"Tier 1 자동 · Tier 2 감시"},{"id":"t6","source":"boundary","target":"activation","kind":"ref","tone":"gate","label":"ACTIVE 쓰기는 로더만"},{"id":"t7","source":"donecheck","target":"completed","kind":"ref","tone":"verify","label":"종료 조건"},{"id":"l1","source":"qreview","target":"feedback","kind":"impl","tone":"activate","label":"확정 사례"},{"id":"l1b","source":"human","target":"feedback","kind":"ref","tone":"activate","label":"구조 확정 사례"},{"id":"l2","source":"completed","target":"metrics","kind":"impl","tone":"store","label":"자동 처리율 · 비용"},{"id":"l3","source":"feedback","target":"registry-read","kind":"impl","tone":"activate","label":"브랜드 사전 · 워크드예제"},{"id":"l4","source":"feedback","target":"corefix","kind":"impl","tone":"deterministic","label":"범용 결함"},{"id":"l5","source":"corefix","target":"golden","kind":"impl","tone":"verify","label":"전 브랜드 회귀"},{"id":"l6","source":"metrics","target":"golden","kind":"ref","tone":"verify","label":"지표 하락 케이스"}]}'::jsonb);
INSERT INTO flow_category (project_slug,slug,title,position) VALUES ('tns','hr','HR',1);
INSERT INTO flow_document (project_slug,category_slug,slug,position,document) VALUES ('tns','hr','hr-overall',0,'{"slug":"hr-overall","title":"HR 통합 업무 흐름","description":"기준정보 설정 → 일상 인사·근태 관리 → 급여 확정 → 명세서 확인","caption":"HR의 네 가지 큰 업무 흐름","direction":"LR","groupDirection":"LR","nodeWidth":270,"howToRead":["법인·조직·직원 정보와 급여 기준을 먼저 설정합니다.","일상 업무에서는 세콤 근태 관리와 직원 신청·전자결재가 나란히 진행됩니다. 승인된 휴가 등은 근태에 함께 반영합니다.","기준정보와 근태·승인 내역을 바탕으로 월 급여를 계산·확정하고 명세서를 발행하면, 직원이 확인하고 다운로드합니다."],"groups":[{"id":"g-master","label":"1. 기준정보 설정","kind":"store"},{"id":"g-daily","label":"2. 일상 인사·근태 관리","kind":"entry"},{"id":"g-payroll","label":"3. 월 급여 계산·확정","kind":"activate"},{"id":"g-payslip","label":"4. 직원 명세서 확인","kind":"activate"}],"nodes":[{"id":"master","group":"g-master","data":{"kind":"store","label":"기준정보 설정","sub":"법인·조직·직원 정보 / 급여 기준"}},{"id":"attendance","group":"g-daily","data":{"kind":"deterministic","label":"세콤 연동 · 근태 관리","sub":"출퇴근 기록 수집 · 근태 반영"}},{"id":"request","group":"g-daily","data":{"kind":"entry","label":"직원 셀프서비스","sub":"본인 정보 조회·수정 / 휴가 등 신청"}},{"id":"approval","group":"g-daily","data":{"kind":"gate","label":"HR 전자결재","sub":"직원 신청 검토·승인 / 인사·근태 반영"}},{"id":"payroll","group":"g-payroll","data":{"kind":"activate","label":"급여 계산 · 확정","sub":["급여 기준·근태·승인 내역 반영","급여 확정 후 명세서 발행"]}},{"id":"payslip","group":"g-payslip","data":{"kind":"activate","label":"직원 급여명세서 확인","sub":"확정 명세서 조회 · 다운로드"}}],"edges":[{"id":"e1","source":"master","target":"attendance","kind":"impl"},{"id":"e2","source":"master","target":"request","kind":"impl"},{"id":"e3","source":"request","target":"approval","kind":"impl"},{"id":"e4","source":"attendance","target":"payroll","kind":"impl"},{"id":"e5","source":"approval","target":"payroll","kind":"impl"},{"id":"e6","source":"payroll","target":"payslip","kind":"impl"}]}'::jsonb);
INSERT INTO flow_category (project_slug,slug,title,position) VALUES ('tns','finance','회계·재무',2);
INSERT INTO flow_document (project_slug,category_slug,slug,position,document) VALUES ('tns','finance','finance-overall',0,'{"slug":"finance-overall","title":"회계·재무 — 전체 흐름","description":"회사 전체 거래 → 전표·장부 → 자금 관리 → 결산·재무제표 → 세무조정 → 신고·납부","caption":"범위 확장 검토안 · 가로 흐름 / 기중 신고는 연말 결산과 병행","direction":"LR","groupDirection":"LR","nodeWidth":270,"howToRead":["업무별 상세는 회계·재무 카테고리의 01~10 차트에서 확인합니다. 영업·국내 구매·해외 수입·운영비의 원천 업무부터 계산서·전표·결산·세목별 신고까지 나누어 설명합니다.","회사 전체 회계처리와 세무신고까지 포함한 범위 확장 검토안입니다. 매출·매입뿐 아니라 급여·경비·자산·차입금·자본 거래를 함께 처리하며, 아래 단계는 구현 완료 상태를 뜻하지 않습니다.","회계 기준과 사업장·회계기간, 계정과목·거래처·세금 구분을 설정하고 전기말 잔액을 이월합니다. 이후 업무 증빙과 금융거래를 수집해 복식부기 전표로 연결합니다.","매출 세금계산서 발행·매입 수취와 상태 추적, 팝빌을 통한 홈택스 전송을 포함합니다. 출고완료 후 미발행, 발행 후 미출고, 품목·수량·금액 불일치는 자동 탐지하고 담당자 조치·재대사·처리 이력을 관리합니다.","은행·카드 자동 수집과 계정과목 자동 매핑으로 전표 초안을 만들고, 담당자가 증빙·차변/대변·세금 구분을 검토해 확정하면 분개장·총계정원장·보조부에 반영합니다. 수동·수정 전표도 지원하고 변경 이력을 보존합니다. 카드 매입 거래 클릭 시 상세 모달을 엽니다.","고객 카드결제는 카드사·PG 정산대기금 → 수수료 확인 → 실제 입금으로 관리합니다. 회사 카드 사용은 지급대기 → 카드대금 출금으로 관리합니다. 채권·채무에 수금·지급을 연결해 잔액과 연체를 추적하며, 정산·수수료·납부 결과도 전표와 장부에 반영합니다.","통합 현금흐름 대시보드는 실제 유입·유출·순현금흐름과 입출금 예정을 구분합니다. 카드 결제와 정산 입출금을 중복 집계하지 않고, 회사 계좌 간 내부이체는 전체 현금흐름에서 상계합니다.","월·연말 결산에서 잔액·합계잔액시산표를 검증하고 재고·매출원가, 감가상각, 외화평가, 미수·미지급 및 선급·선수 항목 등을 조정합니다. 결산 전표를 장부에 반영해 재무상태표·손익계산서·현금흐름표 등 적용 회계기준에 필요한 재무제표·주석을 작성하고, 마감·이월과 재개방 이력을 관리합니다.","부가가치세는 매출·매입 세액과 공제·불공제·영세율 등을 검토하고, 원천세·지급명세서·연말정산은 HR의 급여와 소득 지급 자료를 연계합니다. 이 경로는 세목별 주기에 따라 신고하며 연말 결산 완료를 기다리지 않습니다.","법인세는 결산 자료를 바탕으로 회계와 세법의 차이를 세무조정하고 공제·감면·기납부세액 등을 검토해 신고서·부속서류를 작성합니다. 법인지방소득세 등 지방세도 대상에 맞춰 처리하며, 회계담당자·세무 검토자가 최종 확인합니다.","신고서 작성·검토 → 홈택스·위택스 제출 → 접수 결과 확인 → 납부·환급 대사 → 증빙 보관까지 관리합니다. 반려·오류는 보완 후 재제출하고 수정신고·경정청구 이력도 남깁니다. 전자세금계산서 전송과 세무신고 제출은 별개이며, 세목별 직접 연동 또는 신고파일·외부 신고도구 연계 방식은 별도 확정 대상입니다.","팝빌 계정 가입과 API 이용료는 고객사 부담입니다. 은행·카드 갱신 주기는 제공 서비스 조건에 맞춰 확정하며, 팝빌·홈택스 연동 장애 시 대기·실패 상태를 남기고 복구 후 기존 처리 결과를 확인해 중복 없이 자동 재동기화합니다. 고객 카드 매출·정산 자료의 수집 경로도 계약 카드사·PG에 맞춰 확인합니다."],"groups":[{"id":"g-source","label":"1. 회계 기준·거래 수집","kind":"entry"},{"id":"g-books","label":"2. 전표·장부 처리","kind":"verify"},{"id":"g-daily","label":"3. 자금·정산 관리","kind":"store"},{"id":"g-periodic","label":"기중 신고 · 결산과 병행","kind":"verify"},{"id":"g-close","label":"4. 결산·재무제표","kind":"activate"},{"id":"g-tax","label":"5. 법인세 세무조정","kind":"verify"},{"id":"g-file","label":"6. 신고·납부·사후관리","kind":"activate"}],"nodes":[{"id":"basis","group":"g-source","data":{"kind":"store","label":"회계 기준 · 기초잔액 설정","sub":["사업장·회계기간·계정과목·세금 구분","전기 잔액 이월 · 전표 처리 기준"]}},{"id":"business","group":"g-source","data":{"kind":"entry","label":"회사 전체 거래 · 증빙 수집","sub":["매출·매입·출고 / 수입·통관","급여·경비·자산 / 차입금·자본","세금계산서 발행·수취 · 홈택스 전송"]}},{"id":"money","group":"g-source","data":{"kind":"deterministic","label":"은행 · 카드 · 정산 자료 수집","sub":["계좌 입출금 / 회사 카드 사용","고객 카드결제 / 카드사·PG 정산","팝빌 연동 · 장애 복구 후 재동기화"]}},{"id":"books","group":"g-books","data":{"kind":"verify","label":"증빙 대사 → 전표 확정 → 장부","sub":["출고·계산서 불일치 탐지 · 예외 조치","계정 자동 매핑 · 차변/대변 검토","자동·수동 전표 확정 → 원장 반영"]}},{"id":"funds","group":"g-daily","data":{"kind":"store","label":"채권·채무 정산 · 현금흐름","sub":["수금·지급 / 카드 정산·수수료 반영","잔액·연체 / 유입·유출·순현금흐름","실제·예정 구분 · 내부이체 상계"]}},{"id":"periodic-tax","group":"g-periodic","data":{"kind":"verify","label":"기중 세금 계산 · 신고자료 검토","sub":["부가세: 매출·매입 세액 / 공제 검토","원천세·지급명세서 / HR 연계 연말정산","대상 지방세 포함 · 담당자 검토"],"timing":"세목별 신고 주기"}},{"id":"closing","group":"g-close","data":{"kind":"activate","label":"결산 조정 · 재무제표 작성","sub":["시산표·잔액 / 재고·원가·감가상각","외화평가·기간 귀속 조정 → 결산 전표","재무상태표·손익·현금흐름표 / 마감·이월"],"timing":"월·연말 결산"}},{"id":"corporate-tax","group":"g-tax","data":{"kind":"verify","label":"세무조정 · 법인세 신고서 작성","sub":["회계·세법 차이 조정 / 공제·감면 검토","법인세·법인지방소득세 / 부속서류","회계담당자·세무 검토자 최종 확인"]}},{"id":"filing","group":"g-file","data":{"kind":"activate","label":"신고 제출 → 접수 확인 → 납부","sub":["홈택스·위택스 / 오류 보완·재제출","납부·환급 확인 → 장부·자금 반영","접수증 보관 / 수정신고·경정청구"]}}],"edges":[{"id":"e-basis-books","source":"basis","target":"books","kind":"ref","label":"처리 기준","tone":"store"},{"id":"e-business-books","source":"business","target":"books","kind":"impl"},{"id":"e-money-books","source":"money","target":"books","kind":"impl"},{"id":"e-books-funds","source":"books","target":"funds","kind":"impl"},{"id":"e-books-periodic","source":"books","target":"periodic-tax","kind":"impl","label":"증빙·소득 지급 자료","tone":"verify"},{"id":"e-funds-closing","source":"funds","target":"closing","kind":"impl","label":"장부·잔액 대사"},{"id":"e-closing-tax","source":"closing","target":"corporate-tax","kind":"impl"},{"id":"e-tax-filing","source":"corporate-tax","target":"filing","kind":"impl","label":"결산 기반 신고"},{"id":"e-periodic-filing","source":"periodic-tax","target":"filing","kind":"ref","label":"기중 신고 · 연말 결산과 병행","tone":"verify"}]}'::jsonb);
INSERT INTO flow_document (project_slug,category_slug,slug,position,document) VALUES ('tns','finance','finance-sales',1,'{"slug":"finance-sales","title":"01. 영업·출고·매출·수금","description":"현장·견적·계약 → 조달·출고 → 매출·증빙 → 계좌 수금 / 고객 카드 정산","caption":"티앤에스 업무 참고 · 전체 회계 확장 설계안","direction":"LR","nodeWidth":250,"howToRead":["현행 참고: 티앤에스는 현장·견적·계약과 출고, 세금계산서, 입금 배분을 연결합니다. 현장 정산은 잔여 청구와 미수 잔액으로 판단하고 출고 진행은 별도로 확인합니다.","현행 신규 계산서는 전량 출고 후 전량 발행하는 가드가 있습니다. 선금·중도금·잔금 비율은 결제 예정 관리용이며, 아래 선수금·부분 청구·선발행 예외는 전체 회계 확장 설계로 적용 조건을 별도 확정합니다.","고객에게 먼저 받은 돈은 선수금으로 추적하고, 매출 인식 요건 충족 후 채권과 대체합니다. 출고·인도 사실, 회계상 매출 인식, 세금계산서 발급 시점은 각각 검토하며 결제 자체로 매출을 중복 생성하지 않습니다.","고객 카드결제는 고객 채권을 카드사·PG 정산대기금으로 전환한 뒤 실제 입금·수수료·취소액을 대사하는 설계입니다. 현금 유입은 입금 시 반영하며 카드 사용액과 입금액을 이중 집계하지 않습니다.","어음으로 받는 거래가 있으면 수취·만기·추심/할인·부도 경로를 별도 관리합니다. 어음 수취만으로 현금 유입을 만들지 않습니다. 반품·결제취소·수정계산서는 원거래와 연결해 채권·재고·전표·환급을 함께 조정합니다.","관련 상세: 계산서·예외·연동, 전표·입출금·원장, 부가세 신고. 이 차트는 고객 카드 정산과 선수금 등을 포함한 확장안이며 운영 검증 결과가 아닙니다."],"nodes":[{"id":"order","data":{"kind":"entry","label":"1. 현장·견적 → 계약 확정","sub":["영업: 품목·수량·가격·납품처","선금·중도금·잔금 예정 설정"]},"group":"workflow"},{"id":"procure","data":{"kind":"deterministic","label":"2. 재고 배정 / 조달 요청","sub":["보유 재고·국내 구매·해외 수입","납품 일정과 조달 진행 연결"]},"group":"workflow"},{"id":"ship","data":{"kind":"deterministic","label":"3. 출고·인도 실적 확인","sub":["물류: 피킹·패킹·출고 확정","부분 출고·현장직출 수량 추적"]},"group":"workflow"},{"id":"revenue","data":{"kind":"verify","label":"4. 매출 인식·증빙 검토","sub":["회계: 인도·계약조건·세금 구분","세금계산서/카드 증빙 중복 대사"]},"group":"workflow"},{"id":"ar","data":{"kind":"store","label":"5. 매출·채권 전표 반영","sub":["거래처·현장별 매출/미수 추적","선수금 대체 · 청구 잔액 확인"]},"group":"workflow"},{"id":"advance","data":{"kind":"store","label":"선입금 · 선수금 관리","sub":["납품 전 실제 입금과 계약 연결","매출 전까지 선수금 잔액 유지"]},"group":"workflow"},{"id":"bank","data":{"kind":"deterministic","label":"6. 계좌 입금 배분","sub":["재무: 실제 입금 ↔ 고객 채권","부분 수금·여러 청구 묶음 배분"]},"group":"workflow"},{"id":"card","data":{"kind":"deterministic","label":"6. 고객 카드결제 확인","sub":["고객 채권 → 카드 정산대기금","승인·취소 내역 / 입금 예정"]},"group":"workflow"},{"id":"cardpay","data":{"kind":"deterministic","label":"7. 카드사·PG 정산 대사","sub":["정산대기금 ↔ 입금·수수료·취소","실제 입금만 현금 유입 반영"]},"group":"workflow"},{"id":"bill","data":{"kind":"deterministic","label":"6. 받을어음 수취·추심","sub":["만기·추심/할인·부도 추적","실제 입금 전까지 어음 잔액 관리"]},"group":"workflow"},{"id":"complete","data":{"kind":"activate","label":"8. 수금·현장 정산 확인","sub":["미청구·미수·정산대기 잔액","잔여 건 연체 알림 / 결산 인계"]},"group":"workflow"},{"id":"returns","data":{"kind":"gate","label":"반품·취소 · 차액 조정","sub":["영업·물류·회계: 사유·수량 확인","수정증빙·역분개·환급 검토"]},"group":"workflow"}],"edges":[{"id":"order-procure","source":"order","target":"procure","kind":"impl"},{"id":"procure-ship","source":"procure","target":"ship","kind":"impl"},{"id":"ship-revenue","source":"ship","target":"revenue","kind":"impl"},{"id":"revenue-ar","source":"revenue","target":"ar","kind":"impl"},{"id":"order-advance","source":"order","target":"advance","kind":"impl","label":"선입금 발생"},{"id":"advance-ar","source":"advance","target":"ar","kind":"ref","label":"인식 시 대체","tone":"verify"},{"id":"ar-bank","source":"ar","target":"bank","kind":"impl","label":"계좌 수금"},{"id":"ar-card","source":"ar","target":"card","kind":"impl","label":"카드 수금"},{"id":"ar-bill","source":"ar","target":"bill","kind":"impl","label":"어음 수취"},{"id":"card-cardpay","source":"card","target":"cardpay","kind":"impl"},{"id":"bank-complete","source":"bank","target":"complete","kind":"impl"},{"id":"cardpay-complete","source":"cardpay","target":"complete","kind":"impl"},{"id":"bill-complete","source":"bill","target":"complete","kind":"impl","label":"추심·정산 결과"},{"id":"ar-returns","source":"ar","target":"returns","kind":"impl","label":"반품·취소"},{"id":"returns-complete","source":"returns","target":"complete","kind":"impl","label":"조정 후 잔액"}],"groups":[{"id":"workflow","label":"업무 흐름 · 담당자와 회계 연결"}]}'::jsonb);
INSERT INTO flow_document (project_slug,category_slug,slug,position,document) VALUES ('tns','finance','finance-domestic',2,'{"slug":"finance-domestic","title":"02. 국내 매입·입고·지급","description":"구매 접수 → 국내 PO → 입고·증빙 대사 → 매입채무 → 지급·반품 정산","caption":"티앤에스 업무 참고 · 전체 회계 확장 설계안","direction":"LR","nodeWidth":250,"howToRead":["현행 참고: 국내 구매의 접수·PO·입고와 매입계산서 PO 매칭, 구매 분류별 전표 로직을 참고했습니다. 현행 분류에는 재고와 전시장 비용이 있으며, 이를 모든 구매의 비용 처리 규칙으로 일반화하지 않습니다.","확장 설계: 발주·입고·계산서를 수량·금액 기준으로 대사합니다. 먼저 입고되면 미청구 매입/미지급 추정, 먼저 지급되면 선급금으로 구분하고 후속 증빙·입고 시 정리합니다.","국내 물품 구매는 재고, 운영 소모품·용역은 비용, 장기간 사용하는 물품은 자산 여부를 판단합니다. 전시장 구매도 실제 사용 목적과 자산화 기준에 따라 검토하며 일괄 비용 처리하지 않습니다.","공급사 대금은 승인·지급 예정과 은행 실제 출금을 구분합니다. 분할 지급·합산 지급은 대상 채무별로 배분하고 승인만으로 지급완료나 현금 유출을 만들지 않습니다.","반품은 원 입고·계산서·지급과 연결합니다. 반환 수량, 수정계산서, 미지급 차감 또는 환급/차기 상계까지 대사한 뒤 잔액을 확정합니다. 관련 상세: 계산서·예외·연동, 전표·입출금·원장."],"nodes":[{"id":"request","data":{"kind":"entry","label":"1. 국내 구매 접수","sub":["구매: 현장 수요·재고 보충","전시장·운영 구매 목적 구분"]},"group":"workflow"},{"id":"po","data":{"kind":"deterministic","label":"2. 공급사·PO 확정","sub":["품목·수량·단가·납품처","선금/잔금·지급 예정 확인"]},"group":"workflow"},{"id":"receipt","data":{"kind":"deterministic","label":"3. 입고·검수 확인","sub":["물류: 실제 도착·합격 수량","부분 입고·파손·반품 구분"]},"group":"workflow"},{"id":"invoice","data":{"kind":"deterministic","label":"3. 매입 증빙 수취","sub":["회계: 계산서·카드·영수증","공급사·PO·입고 연결"]},"group":"workflow"},{"id":"review","data":{"kind":"verify","label":"4. 발주·입고·증빙 대사","sub":["수량·금액·세금·누락 확인","재고/비용/자산·공제 여부 검토"]},"group":"workflow"},{"id":"exception","data":{"kind":"gate","label":"불일치 · 증빙 지연 조치","sub":["구매·회계: 재확인·수정 요청","미청구 매입 등 임시 잔액 추적"]},"group":"workflow"},{"id":"ap","data":{"kind":"store","label":"5. 매입 전표 · 채무 반영","sub":["재고/비용/자산 · 매입세액","공급사별 지급 잔액·만기"]},"group":"workflow"},{"id":"prepay","data":{"kind":"store","label":"선급금 지급 · 잔액 추적","sub":["선금 승인 → 실제 출금 확인","입고·증빙 확정 후 대체"]},"group":"workflow"},{"id":"approval","data":{"kind":"gate","label":"6. 지급 요청 · 승인","sub":["재무: 지급 대상·금액·계좌","미지급/중복 지급 확인"]},"group":"workflow"},{"id":"pay","data":{"kind":"deterministic","label":"7. 실제 출금 · 채무 배분","sub":["은행 출금 ↔ 공급사·계산서","분할/합산 지급 · 전표 반영"]},"group":"workflow"},{"id":"return","data":{"kind":"gate","label":"반품 · 매입 조정","sub":["물류·회계: 반출·수정증빙","채무 차감 / 환급·차기 상계"]},"group":"workflow"},{"id":"done","data":{"kind":"activate","label":"8. 구매·지급 잔액 확인","sub":["미입고·미청구·미지급 각각 관리","원장·부가세·결산으로 인계"]},"group":"workflow"}],"edges":[{"id":"request-po","source":"request","target":"po","kind":"impl"},{"id":"po-receipt","source":"po","target":"receipt","kind":"impl"},{"id":"po-invoice","source":"po","target":"invoice","kind":"impl"},{"id":"receipt-review","source":"receipt","target":"review","kind":"impl"},{"id":"invoice-review","source":"invoice","target":"review","kind":"impl"},{"id":"review-ap","source":"review","target":"ap","kind":"impl","label":"대사 완료"},{"id":"review-exception","source":"review","target":"exception","kind":"impl","label":"불일치"},{"id":"exception-ap","source":"exception","target":"ap","kind":"impl","label":"보정·추정 검토 후"},{"id":"po-prepay","source":"po","target":"prepay","kind":"impl","label":"선금 조건"},{"id":"prepay-ap","source":"prepay","target":"ap","kind":"ref","label":"선급 대체","tone":"verify"},{"id":"ap-approval","source":"ap","target":"approval","kind":"impl"},{"id":"approval-pay","source":"approval","target":"pay","kind":"impl"},{"id":"pay-done","source":"pay","target":"done","kind":"impl"},{"id":"receipt-return","source":"receipt","target":"return","kind":"impl","label":"반품 발생"},{"id":"return-done","source":"return","target":"done","kind":"impl","label":"조정 결과"}],"groups":[{"id":"workflow","label":"업무 흐름 · 담당자와 회계 연결"}]}'::jsonb);
INSERT INTO flow_document (project_slug,category_slug,slug,position,document) VALUES ('tns','finance','finance-import',3,'{"slug":"finance-import","title":"03. 해외 수입·외화송금·원가","description":"PO·OC 확정 → 선금·생산 → 선적·통관 → 입고 → 물품·물류비 정산","caption":"티앤에스 업무 참고 · 전체 회계 확장 설계안","direction":"LR","nodeWidth":250,"howToRead":["현행 참고: PO·OC, 선금 조건, 생산, 선적·통관, 라인별 입고, 물품대금/물류비 결의와 원가 배부 로직을 확인했습니다. OC 문서 연결만으로 생산에 진입하지 않으며 담당자 OC 확정과 선금 조건을 함께 봅니다.","B/L 연결과 실제 출항은 다릅니다. ETD는 예정일이며 실제 출항 증거가 아닙니다. 통관 반출은 TNS 창고의 입고 확정이 아니고, 부분 입고는 발주·선적 라인별 합격 수량으로 관리합니다.","송금 회차는 계약 조건에 따라 생산 전·후로 발생합니다. 차트의 선금과 잔금은 대표 경로이며 모든 거래에 선금이나 선적 전 잔금을 강제하지 않습니다.","회계 확장: 인도조건과 자산 인식 시점을 검토해 선급금·미착품·상품·외화채무를 구분합니다. 결제 환율과 장부금액 차이, 수수료는 별도 검토하고 물품 지급과 원가 인식을 같은 사건으로 취급하지 않습니다.","매입가격·포장비·운임·관세 등 직접 원가와 공제 가능한 수입부가세를 구분합니다. 회계 원가는 적용 기준에 따라 배부하며 현행 PO 환율 대비 지급 차이 지표를 법정 회계의 외환차손익과 동일하게 취급하지 않습니다.","거래 종결 시 전량 입고·물품대금·물류비·원가 배부를 각각 확인합니다. 예외 종결해도 미입고·미지급 잔액은 남습니다. 관련 상세: 국내 매입, 전표·입출금·원장, 결산·재무제표, 부가세 신고."],"nodes":[{"id":"po","data":{"kind":"entry","label":"1. 해외 PO · OC 검토·확정","sub":["무역: 브랜드·품목·외화금액","지급 회차·인도조건 확인"]},"group":"workflow"},{"id":"terms","data":{"kind":"gate","label":"2. 선금 조건 확인","sub":["OC 확정 + 선금 회차 여부","문서 연결만으로 생산 진입 금지"]},"group":"workflow"},{"id":"advance","data":{"kind":"deterministic","label":"3. 선금 승인 · 송금 대사","sub":["재무: 결의·실제 출금·외화액","선급금 · 송금수수료 기록"]},"group":"workflow"},{"id":"production","data":{"kind":"deterministic","label":"4. 생산·픽업 진행","sub":["무역: 생산·픽업 실제 진행","선금 없으면 확정 후 바로 진행"]},"group":"workflow"},{"id":"balance","data":{"kind":"deterministic","label":"물품대금 잔금 · 외화채무","sub":["계약 회차별 승인·분할 송금","실제 환율·장부금액 대사"]},"group":"workflow"},{"id":"shipping","data":{"kind":"deterministic","label":"5. 분할 선적 · 실제 출항","sub":["B/L·상업송장·포장명세 연결","예정일과 실제 출항 구분"]},"group":"workflow"},{"id":"customs","data":{"kind":"deterministic","label":"6. 통관 · 수입 증빙 확인","sub":["수입신고·수입계산서·관세","물류비 결의·지급 확인"]},"group":"workflow"},{"id":"recognize","data":{"kind":"verify","label":"자산·외화채무 인식 검토","sub":["인도조건·소유/통제 이전 검토","선급금·미착품·상품 대체"]},"group":"workflow"},{"id":"inbound","data":{"kind":"deterministic","label":"7. 도착 · 라인별 검수 확정","sub":["부분 합격 수량만 재고 반영","창고 입고 / 현장직출 구분"]},"group":"workflow"},{"id":"cost","data":{"kind":"deterministic","label":"8. 물품·포장·물류 원가 배부","sub":["예정/확정 비용 · 수입부가세 구분","배부 기준·미배부 차액 검토"]},"group":"workflow"},{"id":"close","data":{"kind":"activate","label":"9. 수입 거래·잔액 종결 검토","sub":["미입고·물품 미지급·물류 미지급","원가·전표 확인 / 예외 사유 보존"]},"group":"workflow"},{"id":"damage","data":{"kind":"gate","label":"파손·수량차이 · 클레임","sub":["정상 재고와 격리 · 공급사 협의","반품·보상·채무 조정 근거"]},"group":"workflow"}],"edges":[{"id":"po-terms","source":"po","target":"terms","kind":"impl"},{"id":"terms-advance","source":"terms","target":"advance","kind":"impl","label":"선금 있음"},{"id":"terms-production","source":"terms","target":"production","kind":"impl","label":"선금 없음"},{"id":"advance-production","source":"advance","target":"production","kind":"impl","label":"선금 완료"},{"id":"production-shipping","source":"production","target":"shipping","kind":"impl"},{"id":"production-balance","source":"production","target":"balance","kind":"impl","label":"계약 지급 회차"},{"id":"shipping-customs","source":"shipping","target":"customs","kind":"impl"},{"id":"shipping-recognize","source":"shipping","target":"recognize","kind":"impl","label":"인식 시점 검토"},{"id":"customs-inbound","source":"customs","target":"inbound","kind":"impl"},{"id":"customs-cost","source":"customs","target":"cost","kind":"impl","label":"비용·수입 증빙"},{"id":"recognize-cost","source":"recognize","target":"cost","kind":"impl","label":"장부금액"},{"id":"balance-cost","source":"balance","target":"cost","kind":"ref","label":"송금·채무 대사","tone":"verify"},{"id":"inbound-close","source":"inbound","target":"close","kind":"impl"},{"id":"cost-close","source":"cost","target":"close","kind":"impl"},{"id":"inbound-damage","source":"inbound","target":"damage","kind":"impl","label":"미합격·차이"},{"id":"damage-close","source":"damage","target":"close","kind":"impl","label":"조치·미결 잔액"}],"groups":[{"id":"workflow","label":"업무 흐름 · 담당자와 회계 연결"}]}'::jsonb);
INSERT INTO flow_document (project_slug,category_slug,slug,position,document) VALUES ('tns','finance','finance-operations',4,'{"slug":"finance-operations","title":"04. 운영비·자산·차입금","description":"임차료·경비 / 고정자산 / 차입·자본 → 증빙·승인 → 지급 → 잔액·기간 배분","caption":"티앤에스 업무 참고 · 전체 회계 확장 설계안","direction":"LR","nodeWidth":250,"howToRead":["티앤에스 제공 손익계산서에서 급여·복리후생·여비교통·임차료·통신비·수도광열비·감가상각·보험료·차량유지·지급수수료·이자비용 계정의 금액 존재를 확인했습니다. 고객별 실제 금액·거래처·계좌는 차트에 옮기지 않았습니다.","제공 자료는 회계 결과의 근거입니다. 아래 경비 청구·승인·자산 등록·차입 관리의 상세 절차가 현재 구현되었거나 고객에게 확정됐다는 뜻은 아니며 전체 회계 확장 설계입니다.","운영비는 귀속 기간과 과세·공제 여부를 검토합니다. 회사 카드 사용은 카드 미지급금으로, 직원 대납은 직원에게 지급할 금액으로 구분한 뒤 실제 지급을 연결합니다.","자산은 취득·사용 개시·감가상각·이동·매각·폐기까지 관리합니다. 보증금·선급비용은 즉시 비용 처리하지 않고 잔액 또는 기간 배분 대상으로 관리합니다.","차입금 수령은 매출이 아니고 원금 상환은 비용이 아닙니다. 이자·수수료를 구분하고 외화차입금의 환율 차이도 검토합니다. 자본 납입·배당은 손익 거래와 구분하며 실제 적용 여부와 승인 절차는 확인 대상입니다.","급여는 별도 «급여·원천세·지급명세서» 차트로 연결됩니다. 회사 전체 실제 입출금과 지급 예정을 구분하고 미지급·선급·자산·차입 잔액은 결산으로 넘깁니다."],"nodes":[{"id":"expense","data":{"kind":"entry","label":"1. 경비·운영비 발생","sub":["임차료·출장·차량·보험·수수료","직원 청구 / 회사 카드 / 계산서"]},"group":"workflow"},{"id":"asset","data":{"kind":"entry","label":"1. 자산·보증금 취득","sub":["비품·시설·차량 등 자산 검토","보증금·선급비용 구분"]},"group":"workflow"},{"id":"loan","data":{"kind":"entry","label":"1. 차입·자본 거래 발생","sub":["차입·증자·원금 상환·배당","계약·상환 일정·승인 근거"]},"group":"workflow"},{"id":"review","data":{"kind":"verify","label":"2. 업무 목적·증빙 검토","sub":["관리·회계: 귀속 기간·세금 구분","비용/자산/부채/자본 분류"]},"group":"workflow"},{"id":"fix","data":{"kind":"gate","label":"증빙 누락 · 분류 보완","sub":["담당자 확인·추가 증빙 요청","개인 사용·공제 오류 점검"]},"group":"workflow"},{"id":"approval","data":{"kind":"gate","label":"3. 지출·거래 승인","sub":["책임자: 목적·금액·지급처 확인","반려 사유·수정 이력 보존"]},"group":"workflow"},{"id":"journal","data":{"kind":"store","label":"4. 전표 · 지급/수취 잔액","sub":["경비·자산·채무·자본 구분","회사 카드·직원 대납 잔액 분리"]},"group":"workflow"},{"id":"cash","data":{"kind":"deterministic","label":"5. 실제 입출금 대사","sub":["회사 카드대금·직원 경비 지급","차입 수령 / 원금·이자 구분"]},"group":"workflow"},{"id":"register","data":{"kind":"store","label":"6. 보조부·상환 일정 갱신","sub":["자산대장·보증금·차입금 잔액","계약별 만기·상환·지급 예정"]},"group":"workflow"},{"id":"period","data":{"kind":"activate","label":"7. 기간 배분 · 결산 인계","sub":["감가상각·선급 상각·미지급 이자","손익·잔액·현금흐름 반영"]},"group":"workflow"},{"id":"dispose","data":{"kind":"gate","label":"자산 매각·폐기 / 계약 종료","sub":["처분대가·장부가·손익 검토","보증금 회수·잔액 정리"]},"group":"workflow"}],"edges":[{"id":"expense-review","source":"expense","target":"review","kind":"impl"},{"id":"asset-review","source":"asset","target":"review","kind":"impl"},{"id":"loan-review","source":"loan","target":"review","kind":"impl"},{"id":"review-approval","source":"review","target":"approval","kind":"impl","label":"검토 완료"},{"id":"review-fix","source":"review","target":"fix","kind":"impl","label":"보완 필요"},{"id":"fix-approval","source":"fix","target":"approval","kind":"impl","label":"보완 확인"},{"id":"approval-journal","source":"approval","target":"journal","kind":"impl"},{"id":"journal-cash","source":"journal","target":"cash","kind":"impl"},{"id":"cash-register","source":"cash","target":"register","kind":"impl"},{"id":"register-period","source":"register","target":"period","kind":"impl"},{"id":"register-dispose","source":"register","target":"dispose","kind":"impl","label":"종료·처분 발생"},{"id":"dispose-period","source":"dispose","target":"period","kind":"impl","label":"조정 전표·잔액"}],"groups":[{"id":"workflow","label":"업무 흐름 · 담당자와 회계 연결"}]}'::jsonb);
INSERT INTO flow_document (project_slug,category_slug,slug,position,document) VALUES ('tns','finance','finance-invoices',5,'{"slug":"finance-invoices","title":"05. 계산서·불일치·연동 복구","description":"발행·수취 → 원거래 대사 → 예외 조치 → 전송 상태 확인 → 회계·신고 연결","caption":"티앤에스 업무 참고 · 전체 회계 확장 설계안","direction":"LR","nodeWidth":250,"howToRead":["현행 계산서 발행·매입 매칭과 수집 로직을 참고한 확장안입니다. 현행 소스에는 Poooling의 은행거래·계산서·카드 승인 수집 경로도 있으므로, 팝빌 요청 범위와 실제 수집 경로의 통합 방식은 구현 전 확정합니다.","출고완료 후 미발행, 발행 후 미출고, 품목·수량·금액 불일치를 각각 탐지하고 담당자·사유·조치·처리 상태를 추적합니다. 선발행 등의 정당한 예외는 근거를 남겨 관리하며 법정 발급 시점과 현행 전량 출고 가드의 조정은 별도 검토합니다.","매출 발행은 팝빌·홈택스 전송 상태를 확인하고, 매입 수취는 조회 결과를 원거래와 연결합니다. 카드 증빙·세금계산서가 같은 거래를 나타내는지 확인해 매출·매입세액을 중복 반영하지 않습니다.","전송 실패나 응답 유실은 기존 발행·접수 결과부터 조회합니다. 복구 후 미반영 건만 재시도하고 업무키·외부 문서 식별자로 중복을 막습니다. 한도·자격·내용 오류 등 자동 복구 불가 건은 담당자 조치 대기로 남깁니다.","수정·취소는 원 계산서·반품·전표와 연결해 상태와 이력을 유지합니다. 팝빌 계정 가입·API 비용은 고객 부담이며, 계산서 전송 성공은 부가세·법인세 신고 완료를 뜻하지 않습니다."],"nodes":[{"id":"sales","data":{"kind":"entry","label":"1. 매출 증빙 대상","sub":["영업·회계: 거래·출고·인도 내역","발급 시점·카드 증빙 확인"]},"group":"workflow"},{"id":"purchase","data":{"kind":"entry","label":"1. 매입 증빙 수취","sub":["국내 구매·수입·운영비 자료","계산서·영수증·카드 증빙"]},"group":"workflow"},{"id":"match","data":{"kind":"verify","label":"2. 원거래·증빙 자동 대사","sub":["거래처·품목·수량·금액·세액","중복 증빙·누락 확인"]},"group":"workflow"},{"id":"missing","data":{"kind":"gate","label":"미발행 / 미출고","sub":["출고완료·미발행 또는 발행·미출고","담당자·발급/출고 예정 추적"]},"group":"workflow"},{"id":"difference","data":{"kind":"gate","label":"수량·금액·품목 불일치","sub":["발주·출고·계산서 차이 확인","반품·단가 변경·중복 여부"]},"group":"workflow"},{"id":"resolve","data":{"kind":"verify","label":"3. 담당자 조치 · 재대사","sub":["영업·구매·회계: 근거 보완","예외 인정·수정·처리 완료 확인"]},"group":"workflow"},{"id":"route","data":{"kind":"deterministic","label":"4. 발행 / 수취 경로 처리","sub":["매출: 발행 요청·홈택스 전송","매입: 수취 자료·조회 상태 반영"]},"group":"workflow"},{"id":"state","data":{"kind":"verify","label":"5. 외부 처리 결과 조회","sub":["발행·전송·접수·오류 상태 구분","원거래·외부 문서와 연결"]},"group":"workflow"},{"id":"retry","data":{"kind":"gate","label":"장애 · 응답 유실 복구","sub":["대기 기록 → 기존 처리 결과 조회","복구 후 미반영 건만 재동기화"]},"group":"workflow"},{"id":"manual","data":{"kind":"failure","label":"자동 복구 불가 · 담당자 조치","sub":["내용·자격·반복 오류 확인","수정 후 재검증 / 실패 이력"]},"group":"workflow"},{"id":"ledger","data":{"kind":"activate","label":"6. 전표·세무 자료 반영","sub":["원거래의 기존 전표와 대사","중복 분개 없이 상태·차이 반영"]},"group":"workflow"},{"id":"amend","data":{"kind":"gate","label":"수정·취소 증빙 연결","sub":["반품·취소 사유 / 원본 관계 보존","정정 전표·신고 영향 재확인"]},"group":"workflow"}],"edges":[{"id":"sales-match","source":"sales","target":"match","kind":"impl"},{"id":"purchase-match","source":"purchase","target":"match","kind":"impl"},{"id":"match-missing","source":"match","target":"missing","kind":"impl","label":"시점 불일치"},{"id":"match-difference","source":"match","target":"difference","kind":"impl","label":"내용 불일치"},{"id":"missing-resolve","source":"missing","target":"resolve","kind":"impl"},{"id":"difference-resolve","source":"difference","target":"resolve","kind":"impl"},{"id":"match-route","source":"match","target":"route","kind":"impl","label":"정상"},{"id":"resolve-route","source":"resolve","target":"route","kind":"impl","label":"재검증 완료"},{"id":"route-state","source":"route","target":"state","kind":"impl"},{"id":"state-ledger","source":"state","target":"ledger","kind":"impl","label":"결과 확인"},{"id":"state-retry","source":"state","target":"retry","kind":"impl","label":"장애·미확인"},{"id":"retry-ledger","source":"retry","target":"ledger","kind":"impl","label":"처리 확인·재시도 성공"},{"id":"retry-manual","source":"retry","target":"manual","kind":"impl","label":"복구 불가"},{"id":"manual-state","source":"manual","target":"state","kind":"ref","label":"보완 후 재조회","tone":"verify"},{"id":"ledger-amend","source":"ledger","target":"amend","kind":"impl","label":"수정 사유 발생"},{"id":"amend-match","source":"amend","target":"match","kind":"ref","label":"원거래 재대사","tone":"verify"}],"groups":[{"id":"workflow","label":"업무 흐름 · 담당자와 회계 연결"}]}'::jsonb);
INSERT INTO flow_document (project_slug,category_slug,slug,position,document) VALUES ('tns','finance','finance-journals',6,'{"slug":"finance-journals","title":"06. 전표·입출금·원장","description":"계정·기초잔액 → 전표 초안 → 검토·확정 → 입출금 배분 → 원장·현금흐름","caption":"티앤에스 업무 참고 · 전체 회계 확장 설계안","direction":"LR","nodeWidth":250,"howToRead":["현행 참고: 전표 차대 균형 검증, 계산서와 입금 전표, 계산서별 입금 배분 및 역분개 로직이 있습니다. 모든 신규 업무를 완전한 회계로 처리한다는 뜻은 아니며 초안 승인·마감 통제·전체 계정 범위는 확장 설계입니다.","기초잔액은 계정별 잔액과 거래처별 채권·채무, 재고·자산 보조부를 함께 대사합니다. 기존 장부 이관분과 새 거래를 중복 적재하지 않도록 적용 시작일을 정합니다.","거래와 증빙의 회계 인식 이벤트가 전표의 원천입니다. 계정 자동 매핑은 초안이며 차대 균형·귀속 기간·거래처·세금·증빙을 검토한 뒤 확정합니다. 미분류를 임의 계정으로 자동 확정하지 않습니다.","은행 입출금과 승인·카드 사용은 별개 자료입니다. 수금·지급 매칭이 정산 전표를 생성하는 경우 해당 거래를 다시 일반 입출금 전표로 생성하지 않습니다. 여러 채권·채무에 대한 배분 및 미배분 잔액을 보존합니다.","회사 간 거래와 회사 내부 계좌 이체를 구분합니다. 계좌 이체는 양쪽을 연결해 회사 전체 현금 유입·유출에서 상계하고, 카드 매출은 수수료 차감 정산 및 카드 사용대금 출금과 구분합니다.","확정 전표 오류는 원본 삭제 대신 역분개·정정 전표로 처리합니다. 마감 기간 수정은 승인된 재개방 또는 적절한 수정 기간 검토를 거치고 관련 신고에 미치는 영향도 추적합니다."],"nodes":[{"id":"opening","data":{"kind":"store","label":"1. 계정·세금·기초잔액 설정","sub":["회사·기간·원천 적용일 확정","계정 잔액 ↔ 보조부 대사"]},"group":"workflow"},{"id":"event","data":{"kind":"entry","label":"2. 원거래·증빙 인식 이벤트","sub":["매출·매입·급여·경비·수입·자산","정산·결산 조정도 동일 원칙"]},"group":"workflow"},{"id":"draft","data":{"kind":"deterministic","label":"3. 자동 매핑 · 전표 초안","sub":["계정·거래처·부서/현장·세금","수동 입력·원천 이벤트 중복 방지"]},"group":"workflow"},{"id":"review","data":{"kind":"verify","label":"4. 전표 검토·승인","sub":["차대 균형·기간·증빙·세금","미분류·마감기간·중복 점검"]},"group":"workflow"},{"id":"fix","data":{"kind":"gate","label":"오류·미분류 보정","sub":["원자료 확인·계정/기간 보정","검토자·보완 근거 기록"]},"group":"workflow"},{"id":"post","data":{"kind":"store","label":"5. 전표 확정 · 장부 반영","sub":["분개장·총계정원장·보조부","원본·작성자·확정 이력 보존"]},"group":"workflow"},{"id":"bank","data":{"kind":"entry","label":"은행·카드·정산 자료 수집","sub":["실제 입출금·카드 승인/취소","원천 중복·누락·수집 오류 확인"]},"group":"workflow"},{"id":"allocation","data":{"kind":"deterministic","label":"6. 입출금·채권채무 배분","sub":["부분·합산 수금/지급 / 선수·선급","카드 정산·수수료 / 내부이체 대사"]},"group":"workflow"},{"id":"unmatched","data":{"kind":"gate","label":"미매칭·차액 검토","sub":["입금자·지급처·수수료·과오납","잔액 보존 · 담당자 확인"]},"group":"workflow"},{"id":"settlepost","data":{"kind":"deterministic","label":"7. 정산 전표 · 잔액 반영","sub":["배분 확정 결과로 정산 전표","동일 은행거래 중복 분개 방지"]},"group":"workflow"},{"id":"reports","data":{"kind":"activate","label":"8. 원장·시산표·현금흐름","sub":["실제와 예정 구분 / 내부이체 상계","미수·미지급·미매칭 잔액 추적"]},"group":"workflow"},{"id":"reverse","data":{"kind":"gate","label":"확정 취소 · 역분개·정정","sub":["원본 연결 / 마감·신고 영향 검토","잔액·배분 복구 후 수정 전표"]},"group":"workflow"}],"edges":[{"id":"opening-draft","source":"opening","target":"draft","kind":"ref","label":"처리 기준","tone":"verify"},{"id":"event-draft","source":"event","target":"draft","kind":"impl"},{"id":"draft-review","source":"draft","target":"review","kind":"impl"},{"id":"review-fix","source":"review","target":"fix","kind":"impl","label":"보완"},{"id":"fix-post","source":"fix","target":"post","kind":"impl","label":"재검토 통과"},{"id":"review-post","source":"review","target":"post","kind":"impl","label":"승인"},{"id":"post-allocation","source":"post","target":"allocation","kind":"impl","label":"장부 잔액"},{"id":"bank-allocation","source":"bank","target":"allocation","kind":"impl","label":"실제 거래"},{"id":"allocation-unmatched","source":"allocation","target":"unmatched","kind":"impl","label":"미매칭·차액"},{"id":"unmatched-settlepost","source":"unmatched","target":"settlepost","kind":"impl","label":"확인 후 배분"},{"id":"allocation-settlepost","source":"allocation","target":"settlepost","kind":"impl","label":"확정"},{"id":"settlepost-reports","source":"settlepost","target":"reports","kind":"impl"},{"id":"post-reports","source":"post","target":"reports","kind":"ref","label":"발생주의 장부","tone":"verify"},{"id":"post-reverse","source":"post","target":"reverse","kind":"impl","label":"오류·취소"},{"id":"reverse-reports","source":"reverse","target":"reports","kind":"impl","label":"정정 결과"}],"groups":[{"id":"workflow","label":"업무 흐름 · 담당자와 회계 연결"}]}'::jsonb);
INSERT INTO flow_document (project_slug,category_slug,slug,position,document) VALUES ('tns','finance','finance-closing',7,'{"slug":"finance-closing","title":"07. 월·연말 결산·재무제표","description":"거래 마감 점검 → 재고·자산·외화·기간 조정 → 시산표 → 재무제표 → 이월","caption":"티앤에스 업무 참고 · 전체 회계 확장 설계안","direction":"LR","nodeWidth":250,"howToRead":["현행 수입 원가·입고·분개 자료와 고객의 재무상태표·손익계산서·시산표·현금흐름표·자산 관련 파일을 참고한 결산 확장 설계입니다. 장부 파일 존재가 현재 ERP 결산 자동화의 증거는 아닙니다.","은행·채권·채무와 재고·자산·차입금 보조부를 총계정원장과 대사합니다. 일부 거래가 미수·미지급이라는 이유로 매출·비용을 누락하지 않고 기간 귀속과 인식 요건을 판단합니다.","수입 상품은 미착·입고·판매된 수량과 예정/확정 원가를 구분합니다. 통관비·포장비 등 후행 비용이 확정되면 기말 재고와 이미 판매된 매출원가에 미치는 영향을 검토합니다.","외화 자산·부채 평가, 선급·선수·미수·미지급 조정, 감가상각·충당금 등을 적용 회계기준에 맞춰 검토합니다. 추정값에는 근거와 담당자의 검토를 남깁니다.","법인세 등 세액과 필요한 세금비용·부채 조정은 «법인세·지방소득세» 차트에서 검토한 결과로 반영하고 최종 재무제표를 확정합니다. 재무제표의 구성·주석·이연법인세 적용은 회사 회계기준에 맞춰 확정합니다.","결산 검토 중 수정은 장부로 돌아가 재검증합니다. 최종 마감 후 기초잔액을 이월하고 재개방·전표 수정·수정신고 이력을 연계합니다. 현금흐름표와 운영용 입출금 대시보드는 목적과 표시 기준을 구분합니다."],"nodes":[{"id":"cutoff","data":{"kind":"entry","label":"1. 결산 기간·미처리 점검","sub":["회계: 증빙 누락·미확정 전표","영업·구매·HR 담당자 마감 확인"]},"group":"workflow"},{"id":"balances","data":{"kind":"verify","label":"2. 장부·보조부 잔액 대사","sub":["은행·카드·채권·채무·차입금","미매칭·선수·선급·연체 확인"]},"group":"workflow"},{"id":"stock","data":{"kind":"deterministic","label":"3. 재고·수입 원가 조정","sub":["실사·미착·검수·판매 수량 대사","후행 물류비·재고/매출원가 배분"]},"group":"workflow"},{"id":"assets","data":{"kind":"deterministic","label":"3. 자산·기간 귀속 조정","sub":["감가상각·선급 상각·미지급비용","매출 귀속·자산 처분·충당 검토"]},"group":"workflow"},{"id":"fx","data":{"kind":"deterministic","label":"3. 외화·차입금 잔액 평가","sub":["외화채권·채무 / 적용 환율 확인","실현·미실현 환차 / 이자 검토"]},"group":"workflow"},{"id":"adjust","data":{"kind":"verify","label":"4. 결산 전표 검토·확정","sub":["근거·계산·차대·귀속 검증","원장·보조부 함께 반영"]},"group":"workflow"},{"id":"trial","data":{"kind":"verify","label":"5. 합계잔액시산표 검증","sub":["계정 잔액·차대 합계·연결 검증","장부와 보조부 불일치 재확인"]},"group":"workflow"},{"id":"draft","data":{"kind":"deterministic","label":"6. 재무제표·세무 자료 작성","sub":["재무상태·손익·현금흐름·자본","적용 기준별 주석·명세 작성"]},"group":"workflow"},{"id":"tax","data":{"kind":"deterministic","label":"7. 세무조정 결과 반영","sub":["법인세 상세 흐름에서 세액 검토","세금비용·부채 등 결산 전표 보완"]},"group":"workflow"},{"id":"final","data":{"kind":"gate","label":"8. 최종 결산 승인·마감","sub":["책임자: 재무제표·명세 확정","수정 권한·재개방 이력 관리"]},"group":"workflow"},{"id":"carry","data":{"kind":"activate","label":"9. 다음 기간 이월","sub":["기초잔액 ↔ 보조부 이어받기","확정 자료·신고 근거 보존"]},"group":"workflow"},{"id":"correction","data":{"kind":"gate","label":"불일치·마감 후 정정","sub":["원인 전표·원천 자료 추적","재개방/수정 기간·신고 영향 검토"]},"group":"workflow"}],"edges":[{"id":"cutoff-balances","source":"cutoff","target":"balances","kind":"impl"},{"id":"balances-stock","source":"balances","target":"stock","kind":"impl"},{"id":"balances-assets","source":"balances","target":"assets","kind":"impl"},{"id":"balances-fx","source":"balances","target":"fx","kind":"impl"},{"id":"stock-adjust","source":"stock","target":"adjust","kind":"impl"},{"id":"assets-adjust","source":"assets","target":"adjust","kind":"impl"},{"id":"fx-adjust","source":"fx","target":"adjust","kind":"impl"},{"id":"adjust-trial","source":"adjust","target":"trial","kind":"impl"},{"id":"trial-draft","source":"trial","target":"draft","kind":"impl","label":"검증 통과"},{"id":"trial-correction","source":"trial","target":"correction","kind":"impl","label":"차이 발생"},{"id":"correction-adjust","source":"correction","target":"adjust","kind":"ref","label":"수정·재검증","tone":"verify"},{"id":"draft-tax","source":"draft","target":"tax","kind":"impl"},{"id":"tax-final","source":"tax","target":"final","kind":"impl"},{"id":"final-carry","source":"final","target":"carry","kind":"impl"}],"groups":[{"id":"workflow","label":"업무 흐름 · 담당자와 회계 연결"}]}'::jsonb);
INSERT INTO flow_document (project_slug,category_slug,slug,position,document) VALUES ('tns','finance','finance-vat',8,'{"slug":"finance-vat","title":"08. 부가세 신고·납부·환급","description":"매출·매입·수입 증빙 → 과세·공제 검토 → 신고서 → 접수 → 납부·환급","caption":"티앤에스 업무 참고 · 전체 회계 확장 설계안","direction":"LR","nodeWidth":250,"howToRead":["부가가치세 신고는 기중 세목별 주기로 진행하며 연말 결산 완료를 기다리지 않습니다. 티앤에스의 국내 매출·매입, 고객 카드 매출, 수입 증빙과 운영비 자료를 연결하는 확장 설계입니다.","매출세액과 공제 가능한 매입세액을 대사합니다. 카드 매출과 계산서 중복, 공제/불공제, 면세·영세율, 사업장 귀속, 수정증빙과 신고기간을 담당자가 확인합니다. 구체 세율·기한·공제 요건은 신고 대상 시점의 기준으로 적용합니다.","수입신고·수입세금계산서의 부가세는 관세·운임 등 원가와 분리해 검토합니다. 매입세액 공제는 증빙을 수집했다는 이유만으로 자동 확정하지 않습니다.","전표·증빙 합계와 신고서·부속명세를 대사하고 신고 담당자 또는 세무 검토자가 확정합니다. 카드사 정산액은 수수료 차감 후 입금액이므로 이를 카드 매출액으로 대신 사용하지 않습니다.","홈택스 제출은 직접 연동 지원 여부 또는 신고파일·외부 신고도구 경로를 별도 확정합니다. 접수 확인과 납부·환급 완료를 구분하고 실패·반려·수정신고·경정청구를 원 신고와 연결합니다. 계산서 전송은 세무신고 제출과 별개입니다."],"nodes":[{"id":"period","data":{"kind":"entry","label":"1. 신고 사업장·기간 선택","sub":["회계: 과세 유형·대상 기간 확인","기신고 자료·수정 내역 확인"]},"group":"workflow"},{"id":"sales","data":{"kind":"deterministic","label":"2. 매출 증빙 집계","sub":["계산서·현금영수증·카드 매출","카드 승인/취소 · 중복 매출 제외"]},"group":"workflow"},{"id":"purchases","data":{"kind":"deterministic","label":"2. 매입·수입 증빙 집계","sub":["국내 매입·운영비·회사 카드","수입계산서·수정 증빙 연결"]},"group":"workflow"},{"id":"taxclass","data":{"kind":"verify","label":"3. 과세·공제 여부 검토","sub":["과세·면세·영세율 / 공제·불공제","기간·사업장·누락·중복 확인"]},"group":"workflow"},{"id":"fix","data":{"kind":"gate","label":"증빙·전표 보완","sub":["세금 구분 오류·누락 증빙 확인","원거래 수정·재집계"]},"group":"workflow"},{"id":"calc","data":{"kind":"deterministic","label":"4. 세액·신고서·명세 작성","sub":["매출세액·공제세액 등 산정","부속명세 ↔ 장부 합계 대사"]},"group":"workflow"},{"id":"approve","data":{"kind":"gate","label":"5. 신고자료 최종 검토","sub":["회계담당자·세무 검토자","신고서 버전·근거 확정"]},"group":"workflow"},{"id":"submit","data":{"kind":"deterministic","label":"6. 홈택스 신고 제출","sub":["확정된 제출 경로로 전송/업로드","응답 미확인 시 접수 결과 조회"]},"group":"workflow"},{"id":"receipt","data":{"kind":"verify","label":"7. 접수 결과 확인","sub":["접수증·신고금액·상태 보관","반려·오류는 보완 후 재제출"]},"group":"workflow"},{"id":"pay","data":{"kind":"activate","label":"8. 납부·환급 대사","sub":["납부서 ↔ 은행 출금 / 환급 입금","세금 잔액·전표·현금흐름 반영"]},"group":"workflow"},{"id":"amend","data":{"kind":"gate","label":"수정신고·경정청구 검토","sub":["누락·반품·세액 오류 발생","원 신고와 변경 근거·차액 연결"]},"group":"workflow"}],"edges":[{"id":"period-sales","source":"period","target":"sales","kind":"impl"},{"id":"period-purchases","source":"period","target":"purchases","kind":"impl"},{"id":"sales-taxclass","source":"sales","target":"taxclass","kind":"impl"},{"id":"purchases-taxclass","source":"purchases","target":"taxclass","kind":"impl"},{"id":"taxclass-fix","source":"taxclass","target":"fix","kind":"impl","label":"보완"},{"id":"fix-calc","source":"fix","target":"calc","kind":"impl","label":"재검토 완료"},{"id":"taxclass-calc","source":"taxclass","target":"calc","kind":"impl","label":"검토 완료"},{"id":"calc-approve","source":"calc","target":"approve","kind":"impl"},{"id":"approve-submit","source":"approve","target":"submit","kind":"impl"},{"id":"submit-receipt","source":"submit","target":"receipt","kind":"impl"},{"id":"receipt-approve","source":"receipt","target":"approve","kind":"ref","label":"반려·보완","tone":"verify"},{"id":"receipt-pay","source":"receipt","target":"pay","kind":"impl","label":"접수 확인"},{"id":"pay-amend","source":"pay","target":"amend","kind":"impl","label":"사후 수정 필요"},{"id":"amend-calc","source":"amend","target":"calc","kind":"ref","label":"수정 자료","tone":"verify"}],"groups":[{"id":"workflow","label":"업무 흐름 · 담당자와 회계 연결"}]}'::jsonb);
INSERT INTO flow_document (project_slug,category_slug,slug,position,document) VALUES ('tns','finance','finance-payroll',9,'{"slug":"finance-payroll","title":"09. 급여·원천세·지급명세서","description":"HR 근태·급여 → 공제·급여 확정 → 급여 지급 → 원천세·연말정산·명세 제출","caption":"티앤에스 업무 참고 · 전체 회계 확장 설계안","direction":"LR","nodeWidth":250,"howToRead":["기존 HR 요약의 기준정보·세콤 근태·직원 신청/승인·급여 확정·명세서 흐름을 회계·세무까지 확장한 설계입니다. HR 요약 차트는 업무 요구안이며 실제 급여·세무 자동화 운영을 입증하지 않습니다.","티앤에스 회계 자료에서 급여·복리후생 비용을 확인했습니다. 인사정보·소득 유형·과세/비과세 항목·공제·회사 부담금을 확인해 급여와 예수금·미지급 잔액을 구분합니다.","급여 확정은 비용·채무 인식이고 실제 급여 이체는 채무 정산입니다. 회사 부담 보험료와 직원 공제액을 혼합하지 않으며, 지급 실패·부분 지급·추가 정산은 직원별 잔액으로 추적합니다.","원천세와 지방소득세 특별징수, 지급명세서·간이지급명세서, 근로소득 연말정산, 퇴직·사업·기타소득은 해당 소득 유형과 제출 의무에 따라 분기합니다. 모든 유형을 모든 직원에게 일괄 적용하지 않습니다.","연말정산은 증빙·공제 검토 후 추가 징수/환급을 급여에 반영하며 관련 명세와 신고를 대사합니다. 세율·기한·공제 요건은 적용 연도 기준으로 관리하고 직접 신고/파일 연계 방식은 별도 확정합니다."],"nodes":[{"id":"hr","data":{"kind":"entry","label":"1. HR·근태·급여 기준 확인","sub":["인사: 직원·근태·휴가 승인 반영","급여 항목·소득 유형·보험 기준"]},"group":"workflow"},{"id":"calc","data":{"kind":"deterministic","label":"2. 급여·공제 계산","sub":["과세/비과세·세금·보험 공제","회사 부담금·실지급액 구분"]},"group":"workflow"},{"id":"approve","data":{"kind":"gate","label":"3. 급여 검토·확정","sub":["HR·회계: 변동·오류 확인","승인·급여명세서 발행"]},"group":"workflow"},{"id":"journal","data":{"kind":"store","label":"4. 급여·예수금 전표","sub":["급여비용·미지급급여·세금예수금","보험료·회사 부담금 분리"]},"group":"workflow"},{"id":"pay","data":{"kind":"deterministic","label":"5. 급여 실제 이체 대사","sub":["직원별 확정액 ↔ 은행 출금","실패·차액·부분 지급 추적"]},"group":"workflow"},{"id":"returns","data":{"kind":"deterministic","label":"6. 원천세·명세 자료 집계","sub":["근로·퇴직·사업·기타소득별","지급 사실·세금·명세 합계 검토"]},"group":"workflow"},{"id":"annual","data":{"kind":"verify","label":"연말정산 · 추가 징수/환급","sub":["근로소득·공제 증빙 검토","차액을 급여·예수금에 반영"]},"group":"workflow"},{"id":"review","data":{"kind":"verify","label":"7. 신고·제출 대상 검토","sub":["원천세·지방소득세 특별징수","지급/간이지급명세서 대상 확인"]},"group":"workflow"},{"id":"file","data":{"kind":"deterministic","label":"8. 신고·명세 제출 · 접수","sub":["홈택스·위택스 / 신고파일 경로","소득 유형별 주기·접수증 관리"]},"group":"workflow"},{"id":"taxpay","data":{"kind":"activate","label":"9. 세금·보험 납부 대사","sub":["신고·고지 금액 ↔ 실제 출금","예수금·미지급 잔액 정리"]},"group":"workflow"},{"id":"fix","data":{"kind":"gate","label":"오류·반려·수정 처리","sub":["HR/회계 원자료·명세 보완","직원 정산·원 신고 변경 이력"]},"group":"workflow"}],"edges":[{"id":"hr-calc","source":"hr","target":"calc","kind":"impl"},{"id":"calc-approve","source":"calc","target":"approve","kind":"impl"},{"id":"approve-journal","source":"approve","target":"journal","kind":"impl"},{"id":"journal-pay","source":"journal","target":"pay","kind":"impl"},{"id":"pay-returns","source":"pay","target":"returns","kind":"impl"},{"id":"returns-review","source":"returns","target":"review","kind":"impl"},{"id":"returns-annual","source":"returns","target":"annual","kind":"impl","label":"연말정산 시기"},{"id":"annual-review","source":"annual","target":"review","kind":"impl","label":"정산 결과"},{"id":"annual-pay","source":"annual","target":"pay","kind":"ref","label":"추가 지급·징수","tone":"verify"},{"id":"review-file","source":"review","target":"file","kind":"impl"},{"id":"file-taxpay","source":"file","target":"taxpay","kind":"impl","label":"접수 확인"},{"id":"file-fix","source":"file","target":"fix","kind":"impl","label":"반려·오류"},{"id":"fix-review","source":"fix","target":"review","kind":"ref","label":"보완 재검토","tone":"verify"}],"groups":[{"id":"workflow","label":"업무 흐름 · 담당자와 회계 연결"}]}'::jsonb);
INSERT INTO flow_document (project_slug,category_slug,slug,position,document) VALUES ('tns','finance','finance-corporate-tax',10,'{"slug":"finance-corporate-tax","title":"10. 법인세·지방소득세·사후관리","description":"결산 초안 → 세무조정 → 세액·신고서 검토 → 재무제표 확정 → 신고·납부","caption":"티앤에스 업무 참고 · 전체 회계 확장 설계안","direction":"LR","nodeWidth":250,"howToRead":["전체 회계 확장 설계입니다. 결산 장부를 바탕으로 세무조정과 법인세·법인지방소득세 신고서·부속서류를 작성하고 검토·제출·접수·납부·사후관리까지 연결합니다.","회계 손익과 세법상 소득은 다를 수 있으므로 익금·손금 조정과 소득처분·이월 항목, 공제·감면·기납부세액 등을 검토합니다. 적용 항목과 외부 세무조정 등 필요한 검토 체계는 회사의 대상 요건에 맞춰 확정합니다.","티앤에스의 재고·수입 원가·감가상각·차량/경비·이자비용 자료가 결산·세무 검토의 입력입니다. 각 항목의 손금/공제 여부를 계정명만으로 단정하지 않고 계약·증빙·사용 목적을 확인합니다.","계산된 세액과 필요한 세금비용·부채 등 조정을 결산 전표에 반영한 뒤 최종 재무제표·신고 자료를 대사합니다. 결산 세금비용이 바뀌어도 신고 기초와 조정표가 일관되는지 최종 확인합니다.","법인세는 홈택스, 법인지방소득세는 해당 지방세 신고 경로로 관리합니다. 직접 전자신고 API가 있다고 가정하지 않고 신고파일/외부 신고도구 연계를 포함해 제출 경로를 확정합니다. 팝빌 계산서 전송과는 별개입니다.","세목별 접수와 실제 납부·환급을 각각 확인하고 잔액을 장부에 반영합니다. 중간예납 등 기중 의무는 별도 일정으로 관리하며 연말 신고가 끝나야 시작되는 것으로 보지 않습니다. 사후 오류는 수정신고·경정청구와 관련 전표·차액으로 연결합니다."],"nodes":[{"id":"closing","data":{"kind":"entry","label":"1. 결산 장부·명세 수집","sub":["회계: 시산표·재무제표 초안","재고·자산·차입·세금 잔액"]},"group":"workflow"},{"id":"adjust","data":{"kind":"verify","label":"2. 회계·세법 차이 검토","sub":["익금·손금 조정 / 소득처분","감가상각·경비·이자 등 근거 확인"]},"group":"workflow"},{"id":"calc","data":{"kind":"deterministic","label":"3. 과세표준·세액 계산","sub":["이월 항목·공제·감면·기납부세액","법인세·지방소득세 구분"]},"group":"workflow"},{"id":"review","data":{"kind":"gate","label":"4. 세무조정·신고 검토","sub":["회계담당자·세무 검토자","조정표·신고서·부속서류 대사"]},"group":"workflow"},{"id":"final","data":{"kind":"verify","label":"5. 결산 세금 반영·최종 확정","sub":["필요한 세금비용·부채 전표 반영","재무제표·신고서 최종 일치 확인"]},"group":"workflow"},{"id":"national","data":{"kind":"deterministic","label":"6. 법인세 신고 제출","sub":["홈택스 · 확정된 신고 경로","신고서·부속명세·접수 결과"]},"group":"workflow"},{"id":"local","data":{"kind":"deterministic","label":"6. 법인지방소득세 신고","sub":["위택스 등 지방세 신고 경로","사업장별 대상·안분 검토"]},"group":"workflow"},{"id":"receipt","data":{"kind":"verify","label":"7. 세목별 접수 확인","sub":["접수증·버전·신고금액 보존","한 세목 접수로 전체 완료 금지"]},"group":"workflow"},{"id":"pay","data":{"kind":"deterministic","label":"8. 납부·환급·세금 잔액 대사","sub":["신고세액 ↔ 실제 출금·환급","미지급세금·선납세금 정리"]},"group":"workflow"},{"id":"archive","data":{"kind":"activate","label":"9. 신고 근거·기한 관리","sub":["원장·명세·접수증·납부증 보관","중간예납 등 다음 의무 일정"]},"group":"workflow"},{"id":"fix","data":{"kind":"gate","label":"반려·오류 · 수정신고/경정청구","sub":["원 신고·원장·조정표 영향 확인","재검토·차액 납부/환급 추적"]},"group":"workflow"}],"edges":[{"id":"closing-adjust","source":"closing","target":"adjust","kind":"impl"},{"id":"adjust-calc","source":"adjust","target":"calc","kind":"impl"},{"id":"calc-review","source":"calc","target":"review","kind":"impl"},{"id":"review-final","source":"review","target":"final","kind":"impl"},{"id":"final-national","source":"final","target":"national","kind":"impl"},{"id":"final-local","source":"final","target":"local","kind":"impl"},{"id":"national-receipt","source":"national","target":"receipt","kind":"impl"},{"id":"local-receipt","source":"local","target":"receipt","kind":"impl"},{"id":"receipt-pay","source":"receipt","target":"pay","kind":"impl","label":"접수 확인"},{"id":"pay-archive","source":"pay","target":"archive","kind":"impl"},{"id":"receipt-fix","source":"receipt","target":"fix","kind":"impl","label":"반려·오류"},{"id":"archive-fix","source":"archive","target":"fix","kind":"impl","label":"사후 수정 사유"},{"id":"fix-review","source":"fix","target":"review","kind":"ref","label":"변경분 재검토","tone":"verify"}],"groups":[{"id":"workflow","label":"업무 흐름 · 담당자와 회계 연결"}]}'::jsonb);
INSERT INTO flow_category (project_slug,slug,title,position) VALUES ('tns','erd','ERD',3);
INSERT INTO flow_document (project_slug,category_slug,slug,position,document) VALUES ('tns','erd','erd-organization',0,'{"slug":"erd-organization","title":"조직·사용자 ERD","description":"9개 테이블과 참조 관계 · 2026-09-11 로컬 Prisma 스키마 기준","caption":"10개 테이블 · 13개 FK 관계","erdDomain":"organization","direction":"LR","nodeWidth":360,"nodes":[{"id":"account","data":{"kind":"store","label":"account","entity":{"domain":"조직·사용자","external":false,"fieldCount":13,"fields":[{"name":"id","type":"String","optional":false,"keys":["PK"]},{"name":"user_id","type":"String","optional":false,"keys":["FK"]}]}}},{"id":"business_units","data":{"kind":"store","label":"business_units","entity":{"domain":"조직·사용자","external":false,"fieldCount":10,"fields":[{"name":"id","type":"Uuid","optional":false,"keys":["PK"]},{"name":"company_id","type":"Uuid","optional":false,"keys":["FK"]},{"name":"merged_into_id","type":"Uuid","optional":true,"keys":["FK"]}]}}},{"id":"code_values","data":{"kind":"store","label":"code_values","entity":{"domain":"결재·문서·외부 연동","external":true,"fieldCount":8,"fields":[{"name":"id","type":"Uuid","optional":false,"keys":["PK"]},{"name":"code_set_id","type":"Uuid","optional":false,"keys":["FK"]},{"name":"parent_value_id","type":"Uuid","optional":true,"keys":["FK"]}]}}},{"id":"companies","data":{"kind":"store","label":"companies","entity":{"domain":"조직·사용자","external":false,"fieldCount":14,"fields":[{"name":"id","type":"Uuid","optional":false,"keys":["PK"]},{"name":"group_id","type":"Uuid","optional":false,"keys":["FK"]},{"name":"base_currency_id","type":"Uuid","optional":true,"keys":["FK"]},{"name":"merged_into_id","type":"Uuid","optional":true,"keys":["FK"]}]}}},{"id":"departments","data":{"kind":"store","label":"departments","entity":{"domain":"조직·사용자","external":false,"fieldCount":13,"fields":[{"name":"id","type":"Uuid","optional":false,"keys":["PK"]},{"name":"company_id","type":"Uuid","optional":false,"keys":["FK"]},{"name":"parent_id","type":"Uuid","optional":true,"keys":["FK"]}]}}},{"id":"employees","data":{"kind":"store","label":"employees","entity":{"domain":"조직·사용자","external":false,"fieldCount":23,"fields":[{"name":"id","type":"Uuid","optional":false,"keys":["PK"]},{"name":"company_id","type":"Uuid","optional":false,"keys":["FK"]},{"name":"department_id","type":"Uuid","optional":true,"keys":["FK"]},{"name":"user_id","type":"String","optional":true,"keys":["FK","UQ"]}]}}},{"id":"groups","data":{"kind":"store","label":"groups","entity":{"domain":"조직·사용자","external":false,"fieldCount":9,"fields":[{"name":"id","type":"Uuid","optional":false,"keys":["PK"]},{"name":"merged_into_id","type":"Uuid","optional":true,"keys":["FK"]}]}}},{"id":"session","data":{"kind":"store","label":"session","entity":{"domain":"조직·사용자","external":false,"fieldCount":9,"fields":[{"name":"id","type":"String","optional":false,"keys":["PK"]},{"name":"user_id","type":"String","optional":false,"keys":["FK"]}]}}},{"id":"user","data":{"kind":"store","label":"user","entity":{"domain":"조직·사용자","external":false,"fieldCount":13,"fields":[{"name":"id","type":"String","optional":false,"keys":["PK"]}]}}},{"id":"verification","data":{"kind":"store","label":"verification","entity":{"domain":"조직·사용자","external":false,"fieldCount":6,"fields":[{"name":"id","type":"String","optional":false,"keys":["PK"]}]}}}],"edges":[{"id":"account.user","source":"account","target":"user","kind":"impl","tone":"store","label":"0..N : 1"},{"id":"business_units.companies","source":"business_units","target":"companies","kind":"impl","tone":"store","label":"0..N : 1"},{"id":"business_units.business_units","source":"business_units","target":"business_units","kind":"ref","tone":"store","label":"0..N : 0..1"},{"id":"companies.code_values_companies_base_currency_idTocode_values","source":"companies","target":"code_values","kind":"ref","tone":"store","label":"0..N : 0..1"},{"id":"companies.groups","source":"companies","target":"groups","kind":"impl","tone":"store","label":"0..N : 1"},{"id":"companies.companies","source":"companies","target":"companies","kind":"ref","tone":"store","label":"0..N : 0..1"},{"id":"departments.companies","source":"departments","target":"companies","kind":"impl","tone":"store","label":"0..N : 1"},{"id":"departments.parent","source":"departments","target":"departments","kind":"ref","tone":"store","label":"0..N : 0..1"},{"id":"employees.companies","source":"employees","target":"companies","kind":"impl","tone":"store","label":"0..N : 1"},{"id":"employees.departments","source":"employees","target":"departments","kind":"ref","tone":"store","label":"0..N : 0..1"},{"id":"employees.user","source":"employees","target":"user","kind":"ref","tone":"store","label":"0..1 : 0..1"},{"id":"groups.groups","source":"groups","target":"groups","kind":"ref","tone":"store","label":"0..N : 0..1"},{"id":"session.user","source":"session","target":"user","kind":"impl","tone":"store","label":"0..N : 1"}],"howToRead":["각 상자는 실제 테이블이며 PK는 기본 키, FK는 외래 키, UQ는 단일 컬럼 고유 제약입니다. 기본 화면에는 PK·FK만 표시합니다. 테이블을 선택하면 전체 컬럼과 복합 키를 확인할 수 있습니다.","화살표는 FK를 가진 테이블에서 참조 대상 테이블로 향합니다. 왼쪽 숫자는 참조 대상 한 건에 연결될 수 있는 행 수이고, 오른쪽은 각 행이 참조하는 대상 수입니다. 점선은 선택 관계입니다.","참조 배지가 있는 테이블은 다른 영역의 연결 대상입니다. 영역 화면은 해당 영역에서 나가는 모든 FK를 포함합니다. 테이블 선택 시 들어오는 FK도 함께 표시합니다.","Prisma에 선언된 관계만 표시합니다. ID 문자열·JSON 안의 논리적 연결과 DB 전용 인덱스·제약은 포함하지 않습니다. 운영 DB와의 일치 여부는 확인하지 않은 로컬 스키마 스냅샷입니다."]}'::jsonb);
